'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='plainsong'?'Etymonline: https://www.etymonline.com/word/plain-song':w==='plainspoken'?'Etymonline: https://www.etymonline.com/word/plain-spoken':w==='plantlike'||w==='plants'?'Etymonline: https://www.etymonline.com/word/plant':w==='platelike'?'Etymonline: https://www.etymonline.com/word/plate':w==='play area'?'Etymonline: https://www.etymonline.com/word/play':w==='plough'?'Etymonline: https://www.etymonline.com/word/plow':w==='plenteous'?'Etymonline: https://www.etymonline.com/word/plentiful':'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('plainly','Plainly is formed from plain plus the adverb suffix -ly; it means clearly, frankly, or in an uncomplicated way.',C('plainly.s1','清楚地；直截了当地','The notice plainly states that visitors must leave the laboratory before the alarm test begins.','告示清楚写明，警报测试开始前访客必须离开实验室。','The notice plainly states / that visitors must leave / before the alarm test begins.','plainly 修饰 states，强调规定表达清楚、毫无含糊。','读者能从告示直接得知离场要求。'),M('The notice stated the evacuation rule plainly by hiding it in an unreadable footnote and using unexplained abbreviations.','The notice stated the evacuation rule plainly in a clear sentence near the entrance.','晦涩、难找的文字不是清楚直白地说明。','meaning'),[q('What did the notice plainly state?','visitors must leave before the alarm test','visitors should stay beside the equipment','the laboratory would close for a month','告示清楚说明访客何时离开。'),q('What does plainly mean here?','clearly and without ambiguity','in a decorated and indirect way','with deep sorrow in the voice','plainly 在此表示清楚明白地。',1,'meaning'),q('Which instruction is written plainly?','“Turn off the pump before opening the panel.”','“The operational situation may be conducive to deactivation.”','“The panel is a pleasant shade of blue.”','直接清晰的操作句最容易理解。',1,'context'),q('Which word is plainly formed from?','plain plus -ly','plaint plus -ive','planet plus -arium','plainly 由 plain 加副词后缀 -ly 构成。',1,'word-formation')]);
P('plainsong','Plainsong, also called plain-song, translates Latin cantus planus and French plain chant; it is unaccompanied church singing with a single melodic line.',C('plainsong.s1','素歌；单声部礼仪圣咏','The choir sang plainsong in unison, without instruments, during the quiet evening service.','晚间安静的礼拜中，唱诗班齐唱了没有乐器伴奏的素歌。','The choir sang plainsong in unison / without instruments / during the evening service.','plainsong 指礼仪音乐中的单旋律、无伴奏歌唱。','齐唱且没有乐器伴奏符合素歌特点。'),M('The choir called its plainsong a loud instrumental duet with several independent melodic lines.','The choir sang plainsong as one unaccompanied melodic line.','多声部器乐合奏与单声部无伴奏圣咏相反。','meaning'),[q('How did the choir perform the plainsong?','in unison without instruments','with several drums and independent melodies','as a spoken legal complaint','唱诗班无伴奏齐唱单旋律圣咏。'),q('What is plainsong?','unaccompanied liturgical chant with one melodic line','a plan drawing viewed from above','a dance performed on a wooden plank','plainsong 是无伴奏单旋律礼仪圣咏。',1,'meaning'),q('Which performance is plainsong?','a congregation sings one chant melody without instrumental backing','an orchestra plays a multi-part symphony','a soloist speaks a court petition','无伴奏地唱一条圣咏旋律符合 plainsong。',1,'context'),q('Which phrase did plainsong translate historically?','Latin cantus planus','Greek petalon','French petit plan','plainsong 翻译自拉丁语 cantus planus。',1,'word-formation')]);
P('plainspoken','Plainspoken combines plain, “direct,” with spoken; the adjective has been used since the 1670s for frank, unadorned speech.',C('plainspoken.s1','直言不讳的；说话朴实的','The plainspoken engineer told the board that the design was unsafe and showed the failed stress test.','这位直言不讳的工程师告诉董事会，设计并不安全，并展示了未通过的压力测试。','The plainspoken engineer told the board / the design was unsafe / and showed the failed test.','plainspoken 描写坦率、不加修饰的表达方式。','工程师直接指出缺陷并拿出证据。'),M('The plainspoken engineer avoided every direct answer and covered the safety failure with elaborate slogans.','The plainspoken engineer directly explained the safety failure and its evidence.','回避问题并使用华丽口号不是坦率直接。','meaning'),[q('What did the plainspoken engineer tell the board?','the design was unsafe','the design had passed every test','the meeting should be moved to a planetarium','工程师直接指出设计不安全。'),q('What does plainspoken mean?','frank and direct in speech','quietly sung without instruments','likely to expect the worst','plainspoken 指说话坦率直接。',1,'meaning'),q('Which response is plainspoken?','“The pump failed because this valve was installed backward.”','“The operational modality requires further interpretive elaboration.”','“I will not say what caused the failure.”','第一句直截了当地说明故障原因。',1,'context'),q('How is plainspoken formed?','plain plus spoken','plaint plus -ive','plane plus -arium','plainspoken 由 plain 和 spoken 组成。',1,'word-formation')]);
P('plaint','Plaint came through Old French plainte from Latin planctus, “lamentation”; it can mean an expression of grief or, in law, a formal complaint seeking redress.',C('plaint.s1','哀叹；诉苦；法律诉状','The old poem begins with a plaint over the exile, while the case file uses the term for the claimant’s formal grievance.','古诗以对流亡的哀叹开篇，而案卷用这个词指原告的正式申诉。','The old poem begins with a plaint / over exile / while the case file records a formal grievance.','plaint 可指悲伤的表达，也可指法律诉状或正式申诉。','文学和法律语境分别体现其常见用法。'),M('The poem’s plaint celebrated the joyful return, and the court used the word for an informal greeting.','The poem’s plaint mourned the exile, and the court used the word for a formal grievance.','哀叹表达悲伤；正式法律申诉也不是问候语。','meaning'),[q('What does the poem’s plaint express?','grief over exile','a plan for a new factory','praise for a cheerful return','诗中的 plaint 表达对流亡的悲伤。'),q('What can a plaint mean in a legal file?','a formal complaint seeking redress','a person who answers a lawsuit','a melodic church chant','plaint 在法律中可指正式诉状或申诉。',1,'meaning'),q('Which situation contains a plaint?','a written grievance asking a court to remedy a wrong','a visitor plainly reading a safety notice','a choir singing a single melody','向法院请求补救的书面申诉是 plaint。',1,'context'),q('Which Latin noun contributed to plaint?','planctus, “lamentation”','planus, “flat”','planktos, “drifting”','plaint 经古法语源自拉丁语 planctus。',1,'word-formation')]);
P('plaintiff','Plaintiff entered legal English from Anglo-French plaintif, “the aggrieved or complaining party,” related to Old French plainte; it names the person or side that brings a civil case.',[C('plaintiff.s1','原告；提起民事诉讼的人','The plaintiff submitted repair records to show that the landlord had ignored repeated reports of a dangerous leak.','原告提交维修记录，证明房东多次无视危险漏水的报告。','The plaintiff submitted repair records / to show the landlord / had ignored repeated reports.','plaintiff.s1 指在民事法庭起诉他人的个人或团体。','起诉人提交证据主张对方有责任。'),C('plaintiff.s2','原告方；诉讼发起方','At the opening of the hearing, the plaintiff’s side presented its witnesses before the defendant answered.','听证开始时，原告方先传唤证人，随后被告作出回应。','At the opening of the hearing / the plaintiff’s side presented witnesses / before the defendant answered.','plaintiff.s2 也可指一场诉讼中先提出诉讼的一方。','原告方先提出主张，被告方应诉。')],M('The plaintiff answered the lawsuit filed against her, while the other party began the case and asked the court for damages.','The defendant answered the lawsuit, while the plaintiff began the case and sought damages.','提起诉讼并请求赔偿的是 plaintiff；回应诉讼的是 defendant。','meaning'),[q('Who submitted the leak-repair records?','the person bringing the civil case','the judge hearing the case','the building inspector who filed no claim','提交证据起诉的一方是原告。',1,'context'),q('Which side spoke first at the hearing?','the plaintiff’s side','the defendant’s side','the choir’s side','原告方先传唤证人。',2,'context'),q('Who is the plaintiff?','the person or group that brings a civil lawsuit','the person or group that answers the lawsuit','the official who records courtroom attendance','plaintiff 指提起民事诉讼的一方。',1,'meaning'),q('Which French form is related to plaintiff?','plaintif, “aggrieved or complaining party”','planus, “flat surface”','petit, “small”','plaintiff 源自法律用语 plaintif。',1,'word-formation')]);
P('plaintive','Plaintive came from Old French plaintif, “complaining or sorrowful,” related to plainte; it describes a sound or voice that expresses sadness.',C('plaintive.s1','哀伤的；悲切的','A plaintive violin note lingered after the singer finished the verse about her lost home.','歌者唱完失去家园的诗句后，一声悲切的小提琴音仍久久回荡。','A plaintive violin note lingered / after the singer finished / the verse about her lost home.','plaintive 常形容声音、语气或音乐流露悲伤。','小提琴声延续歌曲的哀伤情绪。'),M('The violin played a plaintive melody that sounded triumphant, carefree, and entirely free of sadness.','The violin played a plaintive melody that sounded sorrowful and mournful.','欢快、无忧的旋律并不表达 plaintive 的哀伤。','meaning'),[q('What remained after the verse?','a sorrowful violin note','a legal complaint form','a drawing of a planet','诗句之后留下的是悲切的小提琴音。'),q('What does plaintive describe?','expressing sorrow, especially through sound or voice','plainly setting out a legal plan','a small body orbiting the Sun','plaintive 指声音或语气带有哀伤。',1,'meaning'),q('Which sound is plaintive?','a soft, mournful call from someone saying goodbye','a bright fanfare welcoming a victory','a dry click from a machine switch','悲伤的告别声具有 plaintive 的特点。',1,'context'),q('Which noun is plaintive related to?','plaint','plank','planetarium','plaintive 与 plaint 同源，二者都涉及哀诉。',1,'word-formation')]);
P('plait','Plait came through French forms from Latin plicare, “fold”; as a noun it is an interwoven length of hair, and as a verb it means weave strands together.',[C('plait.s1','辫子；编好的发辫','She tied a ribbon around the plait before the dancer stepped onto the stage.','舞者登台前，她在编好的辫子上系了一条丝带。','She tied a ribbon around the plait / before the dancer / stepped onto the stage.','plait.s1 作名词指编织在一起的一束头发。','丝带系在已经编好的发辫上。'),C('plait.s2','编成辫子；交织','The craft teacher showed the children how to plait three strips of straw into a sturdy mat.','手工老师教孩子们如何把三条稻草编成结实的垫子。','The teacher showed the children / how to plait three strips of straw / into a sturdy mat.','plait.s2 作动词，表示把头发、稻草等交织编在一起。','三股材料被交织成垫子。')],M('She plaited the hair by leaving every strand separate and loose, with no strands crossing one another.','She plaited the hair by weaving the strands over and under one another.','头发彼此不交织就没有编成辫子。','meaning'),[q('Where did she tie the ribbon?','around the dancer’s finished braid','around a wooden plank','on the plaintiff’s case file','丝带系在编好的辫子上。',1,'context'),q('What does plait mean as a verb?','weave strands together','cut a flat board into sections','write a complaint to a court','plait 作动词表示编织、编辫子。',2,'meaning'),q('Which action plaits straw?','interweaving three strips to make a mat','laying three strips side by side without crossing','painting the strips as a planet model','交织稻草条制成垫子是 plait。',2,'context'),q('Which Latin verb underlies plait?','plicare, “to fold”','planctus, “lamentation”','planasthai, “to wander”','plait 源于拉丁语 plicare。',1,'word-formation')]);
P('plan','Plan entered English through French from Latin planum, “flat surface”; it can be an intended course of action, a drawing from above, or a verb meaning decide in advance.',[C('plan.s1','计划；方案','The team’s plan is to test the backup pump before the rainy season begins.','团队的计划是在雨季开始前测试备用水泵。','The team’s plan / is to test the backup pump / before the rainy season begins.','plan.s1 是对未来做法的设想或安排。','团队预先确定测试安排。'),C('plan.s2','平面图；俯视图','The architect checked the plan to confirm that the kitchen door would not block the hallway.','建筑师查看平面图，确认厨房门不会挡住走廊。','The architect checked the plan / to confirm the kitchen door / would not block the hallway.','plan.s2 指从上方表示建筑或机器的详细图纸。','平面图用于查看房间布局。'),C('plan.s3','计划；预先决定','We planned to inspect the bridge at dawn, when traffic on the road was light.','我们计划在天亮时检查桥梁，那时路上车辆较少。','We planned to inspect the bridge / at dawn / when road traffic was light.','plan.s3 作动词表示事先决定将要做的事，常接 to do。','检查时间在行动前就已安排。')],M('The team planned testing the pump tomorrow, but the schedule says it has made no advance decision.','The team planned to test the pump tomorrow, according to the agreed schedule.','此处 plan 作“预先决定”时应说 plan to do，且既有安排与“未作决定”矛盾。','grammar'),[q('What does the team intend to test before the rainy season?','the backup pump','the kitchen doorway','a planetarium dome','计划测试备用水泵。',1,'context'),q('What did the architect inspect?','a top-down drawing of the rooms','a list of rainy-season forecasts','a woven straw mat','建筑师查看的是建筑平面图。',2,'context'),q('Which sentence uses plan as a verb correctly?','They plan to inspect the bridge at dawn.','They plan inspecting the bridge at dawn.','They plan the bridge to inspected at dawn.','plan 后常用 to do 表示计划做某事。',3,'grammar'),q('Which noun meaning fits “a plan for evacuation”?','an idea for what to do in the future','a flat drawing of a building only','a section of woven hair','这里 plan 指未来行动方案。',1,'meaning')]);
P('plane','Plane is a homonym with several histories: the aircraft sense shortens aeroplane, the geometric sense comes from Latin planum “flat surface,” and the woodworking tool from French/Latin forms for making level.',[C('plane.s1','飞机','The plane circled once above the airport because a storm temporarily blocked the runway.','暴风雨暂时封闭跑道，飞机便在机场上空盘旋了一圈。','The plane circled above the airport / because a storm / blocked the runway.','plane.s1 是 aeroplane 的缩略形式，指有机翼的飞行器。','飞机等待跑道重新开放。'),C('plane.s2','平面','In geometry, every point on the plane is the same distance from the center of the circle.','在几何平面上，圆周上的每一点到圆心距离相同。','In geometry / every point on the plane / has the same distance from the center.','plane.s2 指完全平坦的几何表面。','这里的 plane 是数学平面，不是飞机。'),C('plane.s3','刨子','The carpenter pushed the plane along the cabinet door to remove a raised edge.','木匠沿柜门推刨子，削去凸起的边缘。','The carpenter pushed the plane / along the cabinet door / to remove a raised edge.','plane.s3 指用刀刃刨平木材的工具。','工具削平木门表面。'),C('plane.s4','层次；水平','The debate moved to a more abstract plane when the speakers began discussing justice rather than costs.','发言者开始讨论正义而非成本时，辩论转到了更抽象的层面。','The debate moved to a more abstract plane / when the speakers discussed justice / rather than costs.','plane.s4 可比喻思想、质量或存在的层面。','话题从具体成本转向抽象原则。')],M('The carpenter used a plane to fly the cabinet door above the airport, then measured its geometric level.','The carpenter used a plane to smooth the cabinet door, while the aircraft circled above the airport.','木工刨子是工具，不是飞行器；句子混淆了同形异义词。','confusable'),[q('Why did the aircraft circle above the airport?','a storm blocked the runway','the carpenter needed to smooth a door','the geometry class moved to an abstract topic','飞机因跑道受阻而盘旋。',1,'context'),q('What is the plane in the geometry sentence?','a flat mathematical surface','an aircraft waiting to land','a tool for smoothing wood','数学中的 plane 是平面。',2,'meaning'),q('Which tool did the carpenter push along the door?','a bladed woodworking tool for smoothing','an aircraft with wings','a flat surface in a geometry proof','木匠用刨子削平凸起边缘。',3,'context'),q('What does “a more abstract plane” mean?','a higher level or sphere of thought','a machine that flies above a city','a board used in carpentry','此处 plane 指思想讨论的层面。',4,'meaning')]);
P('planet','Planet came through French and Late Latin from Greek planētēs, “wanderer,” because planets appear to move against the fixed stars; it means an orbiting celestial body or, informally, Earth as a whole.',[C('planet.s1','行星','Astronomers confirmed that the planet has a rocky surface and follows a stable orbit around its star.','天文学家确认这颗行星有岩石表面，并沿稳定轨道绕恒星运行。','Astronomers confirmed / the planet has a rocky surface / and follows an orbit around its star.','planet.s1 指围绕恒星运行的巨大天体。','天体绕恒星公转，符合行星义。'),C('planet.s2','地球；整个世界','If the coastal wetlands disappear, the planet will lose one of its most effective natural defenses against storms.','如果沿海湿地消失，地球将失去抵御风暴最有效的天然屏障之一。','If the wetlands disappear / the planet will lose / a natural defense against storms.','planet.s2 在 the planet 结构中可非正式指地球整体。','这里描述全球环境影响。')],M('Astronomers called the orbiting body a planet, although it neither orbits a star nor has any path through space.','Astronomers called the body a planet because it follows an orbit around its star.','围绕恒星运行是此处称为 planet 的关键信息。','meaning'),[q('What does the discovered planet orbit?','a star','the greenhouse tomato plant','a court building','该天体沿轨道绕恒星运行。',1,'context'),q('What does the planet refer to in the wetland sentence?','Earth considered as a whole','a rocky body orbiting another star','an astronomical theatre','这里 the planet 指整个地球。',2,'meaning'),q('Which object fits planet.s1?','a large round body traveling around a star','a small leaf stalk','a wooden board','围绕恒星运行的球状天体是行星。',1,'meaning'),q('Why were early planets called wanderers?','they appeared to move against the fixed stars','they were woven from wandering strands','they were drawn as flat building plans','行星相对恒星背景看似移动，因此称“游星”。',1,'word-formation')]);
P('planetarium','Planetarium combines planeta, “planet,” with Latin -arium, “a place for”; it first named a model of planetary motions and now commonly means a domed theatre projecting the night sky.',C('planetarium.s1','天文馆；天象厅','At the planetarium, the presenter dimmed the dome and projected the winter constellations above the audience.','在天文馆里，讲解员调暗穹顶灯光，把冬季星座投影到观众上方。','At the planetarium / the presenter dimmed the dome / and projected winter constellations.','planetarium 指用穹顶投映星空供观众观看的场馆。','穹顶上呈现星座，符合天文馆场景。'),M('The planetarium projected the stars onto an outdoor football field with no dome or indoor theatre.','The planetarium projected the stars onto the theatre’s domed ceiling.','天文馆的典型投影面是室内穹顶，而不是露天球场。','meaning'),[q('What appeared above the audience?','projected winter constellations','a courtroom petition','a wooden plank','天文馆穹顶投影了冬季星座。'),q('What is a planetarium?','a theatre that projects celestial scenes onto a dome','a factory producing chemicals from oil','a flat drawing of a house','planetarium 是投映星空的穹顶场馆。',1,'meaning'),q('What did the presenter do before the show?','dimmed the dome','plaited the audience’s hair','closed the airport runway','讲解员调暗穹顶以便观看投影。',1,'context'),q('What does Latin -arium contribute to planetarium?','a place or thing associated with something','a person who expects the worst','a tool that smooths wood','-arium 常构成表示场所或相关事物的词。',1,'word-formation')]);
P('planetary','Planetary comes from planet plus the adjective suffix -ary; it means relating to a planet, or on a scale affecting the whole world.',C('planetary.s1','行星的；全球范围的','The probe recorded planetary dust around the young world, while the report described the launch as a planetary-scale project.','探测器记录了这颗年轻行星周围的尘埃，报告则把此次发射称为全球规模的项目。','The probe recorded planetary dust / around the young world / while the report described a planetary-scale launch.','planetary 可表示与行星有关，也可表示规模涉及整个地球。','句中同时示范天文学义和“全球规模”义。'),M('The team called the mission planetary even though it concerned only a local garden and no planet or worldwide issue.','The team called the mission planetary because it studied a planet and involved partners worldwide.','既不涉及行星也非全球范围，不能称为 planetary。','meaning'),[q('What did the probe record?','dust around a young planet','leaves around a petiole','a legal plaint','探测器记录了行星周围的尘埃。'),q('What does planetary mean in “planetary-scale project”?','worldwide in scale','limited to one room','expressing sorrow in a voice','planetary-scale 表示全球规模。',1,'meaning'),q('Which mission is planetary?','a study of a planet’s atmosphere','a plan for one neighborhood meeting','a tool for smoothing a cabinet door','研究行星大气的任务与行星有关。',1,'context'),q('Which noun is the base of planetary?','planet','plankton','plaintiff','planetary 由 planet 加 -ary 构成。',1,'word-formation')]);
P('planetoid','Planetoid was formed from planet plus Greek-derived -oid, “resembling”; it refers especially to a minor planet or asteroid orbiting the Sun.',C('planetoid.s1','小行星；微型行星','The observatory tracked a planetoid whose orbit carried it between Mars and Jupiter.','天文台追踪到一颗小行星，其轨道位于火星与木星之间。','The observatory tracked a planetoid / whose orbit carried it / between Mars and Jupiter.','planetoid 指类似行星的小天体，常用于小行星。','轨道位于火星和木星之间符合小行星描述。'),M('The telescope identified a planetoid as a giant star fixed at the center of the galaxy.','The telescope identified a planetoid as a small body orbiting the Sun.','小行星是绕太阳运行的小天体，不是固定的巨星。','meaning'),[q('Where did the planetoid travel?','between the orbits of Mars and Jupiter','inside the planetarium dome','along the laboratory hallway','小行星运行在火星和木星轨道之间。'),q('What is a planetoid?','a minor planet or asteroid','a major star fixed in the sky','a theatre for viewing projected stars','planetoid 指小行星或类似行星的小天体。',1,'meaning'),q('Which object could be called a planetoid?','a small rocky body orbiting the Sun','a leaf floating in a pond','a chemical made from petroleum','绕太阳运行的小型岩石天体可称 planetoid。',1,'context'),q('What does -oid mean in planetoid?','resembling or like','a person who plans','a place for viewing','-oid 表示“像……的、类似……的”。',1,'word-formation')]);
P('plank','Plank came from Old French and Late Latin planca, “broad board”; it is a long, thick piece of wood used in construction.',C('plank.s1','厚木板','The workers laid a plank across the muddy gap so the cart could reach the storage shed.','工人把一块厚木板架在泥泞的沟上，让手推车能到达仓库。','The workers laid a plank across the gap / so the cart / could reach the shed.','plank 指长而厚的木板。','木板被用作临时通道。'),M('The workers laid a plank across the gap, but it was a soft flower petal only a few millimeters wide.','The workers laid a thick wooden plank across the gap.','花瓣不是可承重的厚木板。','meaning'),[q('Why did the workers lay a plank across the gap?','to let the cart reach the shed','to show the planetarium audience stars','to file a court complaint','木板搭桥让手推车通过。'),q('What is a plank?','a long, thick board of wood','a single melodic church chant','a person who brings a lawsuit','plank 指长而厚的木板。',1,'meaning'),q('Which material could be cut into a plank?','a thick timber beam','a flower petal','a stream of plankton','木材可锯成厚木板。',1,'context'),q('Which source word meant a broad slab or board?','Late Latin planca','Greek planētēs','Latin planctus','plank 源自表示宽板的晚期拉丁语 planca。',1,'word-formation')]);
P('plankton','Plankton was coined through German from Greek plankton, “drifting”; it refers to small organisms in water that drift with currents and generally cannot swim against them.',C('plankton.s1','浮游生物','A blue whale filters plankton from the water, consuming tiny drifting organisms by the ton.','蓝鲸从海水中过滤浮游生物，一次可摄入大量微小漂浮生物。','A blue whale filters plankton / from the water / consuming tiny drifting organisms.','plankton 是漂浮在海洋或湖泊中的微小生物群。','鲸鱼过滤水体摄食浮游生物。'),M('The report classified fast-swimming tuna as plankton because they actively chase prey against strong currents.','The report classified tiny drifting organisms as plankton because they move with the currents.','能主动逆流追捕猎物的鱼类不属于随流漂浮的 plankton。','meaning'),[q('What does the blue whale filter from the water?','tiny drifting organisms','wooden planks','petals and petioles','蓝鲸摄食微小的浮游生物。'),q('What is plankton?','small organisms that drift in water','large animals that swim quickly against currents','a tool used to smooth wood','plankton 指水中漂浮的微小生物。',1,'meaning'),q('Which organism is plankton?','a microscopic organism carried by a lake current','a tuna steering against the current','a whale crossing the ocean','随湖流漂移的微小生物属于 plankton。',1,'context'),q('What does Greek plankton suggest?','drifting or wandering','a flat wooden board','a legal complaint','plankton 源于表示“漂浮、漂移”的希腊词。',1,'word-formation')]);
P('planner','Planner is the agent noun from plan; it names someone who arranges future actions or, in newer use, a book or device for organizing them.',C('planner.s1','规划者；计划者','The city planner met residents to revise the bus routes before the new housing opened.','城市规划师在新住宅区开放前与居民会面，修改公交线路。','The city planner met residents / to revise bus routes / before the new housing opened.','planner.s1 指制定安排的人，尤指城镇规划人员。','规划师与居民协商公交路线。'),M('The planner organized the town schedule, although no person or device made or recorded any arrangements.','The planner organized the town schedule and recorded the revised bus routes.','若没有负责安排的人或工具，就不能说 planner 做了规划。','meaning'),[q('What did the city planner revise?','bus routes near the new housing','the flower petals in a greenhouse','the orbit of a planetoid','城市规划师修改公交线路。'),q('Who is a planner?','someone who arranges future actions or layouts','someone who brings a lawsuit','an organism drifting in water','planner 指制定计划或规划的人。',1,'meaning'),q('Which person is a planner?','an event coordinator arranging speakers and rooms','a visitor reading a clear notice','a carpenter smoothing a cabinet','安排活动流程和场地的人是 planner。',1,'context'),q('From which verb is planner formed?','plan','plait','plantation','planner 是 plan 加施事者后缀形成的名词。',1,'word-formation')]);
P('planning','Planning is the verbal noun from plan; it means the activity of deciding in advance how something will be done.',C('planning.s1','规划；计划制定','Careful planning gave the rescue crew a route around the flooded bridge before nightfall.','周密的规划让救援队在天黑前找到绕过被淹桥梁的路线。','Careful planning gave the crew a route / around the flooded bridge / before nightfall.','planning 指事先安排步骤、资源或路线的过程。','救援路线在出发前已经规划好。'),M('The crew reached the bridge through careful planning, although nobody had chosen a route or prepared beforehand.','The crew reached the bridge through careful planning that set a safe route in advance.','没有事先选择路线或准备就不属于 careful planning。','meaning'),[q('What did planning give the rescue crew?','a route around the flooded bridge','a new name for the bridge','a plaintive song','规划提供了绕过被淹桥梁的路线。'),q('What does planning mean?','the activity of deciding beforehand what to do','the act of turning a process unfair','a group of organisms drifting in water','planning 指提前安排和决定。',1,'meaning'),q('Which task requires planning?','assigning supplies and a safe route before a night rescue','choosing a route only after becoming lost','reading the bridge name aloud','夜间救援前安排物资和路线需要 planning。',1,'context'),q('Which verb is the base of planning?','plan','plant','plait','planning 是动词 plan 的动名词/名词形式。',1,'word-formation')]);
P('plant','Plant is from Latin planta, “shoot or cutting,” and also developed a verb and industrial sense; it can mean a living organism, a factory, put something in soil, or secretly place evidence.',[C('plant.s1','植物','The plant beside the window grew new leaves after the gardener moved it into brighter light.','园丁把窗边的植物移到光线更好的地方后，它长出了新叶。','The plant beside the window grew new leaves / after the gardener moved it / into brighter light.','plant.s1 指能生长、有叶和根的植物。','植物因光照改善而长出新叶。'),C('plant.s2','工厂；工业设施','The power plant shut down one turbine while technicians replaced a damaged cooling valve.','技术人员更换损坏的冷却阀时，发电厂关闭了一台涡轮机。','The power plant shut down one turbine / while technicians replaced / a cooling valve.','plant.s2 指工厂或工业生产设施及其机器。','发电设施检修涡轮和阀门。'),C('plant.s3','种植；栽种','Each volunteer planted a young oak beside the restored stream.','每位志愿者都在修复后的溪流旁栽下一棵小橡树。','Each volunteer planted a young oak / beside the restored stream.','plant.s3 作动词，表示把种子或幼苗放入土中让其生长。','志愿者将树苗栽入土中。'),C('plant.s4','栽赃；暗中放置','Investigators proved that someone had planted the stolen watch in the driver’s bag to make him look guilty.','调查人员证明，有人把失窃手表偷偷放进司机的包里，想让他看起来有罪。','Investigators proved / someone had planted the stolen watch / in the driver’s bag.','plant.s4 作动词可指暗中放置证物，意图使他人被怀疑或定罪。','物品被故意藏入他人包中。')],M('The investigators planted the watch honestly by leaving it in its owner’s hand and never hiding it in anyone’s bag.','The investigators found that someone planted the watch in the driver’s bag to frame him.','公开交还物品不是栽赃；把赃物藏到他人包里才是 plant 的此义。','meaning'),[q('What happened to the window plant?','it grew new leaves in brighter light','it generated electricity at a factory','it was hidden in a driver’s bag','植物在更亮处长出新叶。',1,'context'),q('What did technicians repair at the power plant?','a cooling valve while one turbine was shut down','a tree beside a stream','a case file in a courtroom','发电厂检修冷却阀时停了一台涡轮机。',2,'context'),q('Which sentence uses plant to mean “put into soil”?','Volunteers planted oak saplings beside the stream.','The power plant replaced its turbine.','Someone planted a watch in the driver’s bag.','把橡树苗栽入土中是 plant 的种植义。',3,'meaning'),q('What did “planted the stolen watch” mean in the investigation?','hid it in someone’s bag to make that person seem guilty','grew a watch from a seed','repaired the watch at a factory','plant 这里表示栽赃、暗中放置证物。',4,'meaning')]);
P('plantation','Plantation came from Latin plantationem, “a planting”; it now commonly means either a large farm growing one crop or an area planted with trees for timber.',[C('plantation.s1','种植园；大型单一作物农场','The tea plantation employs seasonal crews to harvest leaves from the steep hillside rows.','这座茶叶种植园雇用季节工采摘陡坡上一排排茶树的叶子。','The tea plantation employs seasonal crews / to harvest leaves / from the hillside rows.','plantation.s1 指种植茶、棉花等作物的大型农场。','大面积茶园雇人采收茶叶。'),C('plantation.s2','人工林；木材种植林','The forestry agency replanted the burned slope as a plantation of fast-growing pine for future timber.','林业部门把烧毁的山坡重新种成速生松人工林，以供未来采伐木材。','The agency replanted the slope / as a plantation of pine / for future timber.','plantation.s2 指为获得木材而栽种树木的区域。','整片山坡栽植松树用于木材生产。')],M('The forestry agency called the slope a tree plantation, although it had never planted any trees there.','The forestry agency created a tree plantation by planting pines across the slope.','没有种树的地块不是人工林。','meaning'),[q('What grows across the hillside plantation?','tea bushes harvested by seasonal crews','only native wildflowers never cultivated','industrial turbines','茶园成片种植茶树供采摘。',1,'context'),q('What is the forestry plantation intended to provide?','pine timber in the future','a court petition','a single melodic chant','人工林用于未来木材生产。',2,'context'),q('What does plantation.s1 mean?','a large farm growing a crop such as tea or cotton','a small flowerpot for one houseplant','a factory that manufactures turbines','plantation.s1 指种植经济作物的大型农场。',1,'meaning'),q('What does plantation.s2 describe?','land planted with trees for timber','land left without any trees','a legal filing sent to court','plantation.s2 指为木材而种树的地块。',2,'meaning')]);
P('planter','Planter is formed from plant plus agent suffix -er; it can name a person or machine that plants crops, a historical plantation owner, or a container for growing plants.',C('planter.s1','播种者；种植机；种植盆','The gardener filled a ceramic planter with soil, while the farm used a mechanical planter to sow corn in straight rows.','园丁在陶制花盆里装土，农场则用播种机把玉米播成整齐的行。','The gardener filled a ceramic planter / while the farm used a mechanical planter / to sow corn.','planter.s1 可指种植的人或机器，也可指栽种植物的容器。','同一场景对比花盆和播种机两义。'),M('The farmer used the planter to harvest fully grown corn without planting seeds or seedlings.','The farmer used the planter to place corn seeds in rows for growth.','播种机用于种下作物，不是收割成熟玉米。','meaning'),[q('What did the gardener put soil into?','a ceramic container for growing plants','a courtroom petition','a plane’s cabin','园丁把土装进栽种用的花盆。'),q('What did the farm’s mechanical planter do?','sow corn seeds in straight rows','harvest mature corn ears','smooth the wood of a cabinet','播种机把玉米种成整齐的行。',1,'context'),q('Who could be called a planter in the agent sense?','a worker who sets seedlings into the ground','a person who only files a lawsuit','a singer performing plainsong','把幼苗栽入土中的人可称 planter。',1,'meaning'),q('Which base verb forms planter?','plant','plan','plait','planter 由 plant 加 -er 构成。',1,'word-formation')]);
P('planting','Planting is the verbal noun of plant, from Old English plantung; it means the act of setting plants into soil or a planted area.',C('planting.s1','种植；种植物','The spring planting began as soon as the soil was warm enough for the bean seeds.','土壤温度适合豆种后，春季播种便开始了。','The spring planting began / as soon as the soil / was warm enough for bean seeds.','planting 可指栽种的行为，也可指人工种植的一片植被。','语境中指播种活动。'),M('The spring planting started after the gardeners removed every seed and refused to put any plants in the soil.','The spring planting started when gardeners placed bean seeds in the prepared soil.','没有种子或栽种行为，就没有开始播种。','meaning'),[q('When did the spring planting begin?','when the soil was warm enough for bean seeds','after the seeds had all been removed','when the harvest had already ended','土壤适合种豆后开始播种。'),q('What does planting mean?','the act of putting plants or seeds into soil','the act of serving food on a plate','the place where trains wait','planting 指播种、栽种的行为。',1,'meaning'),q('Which sentence uses planting for a planted area?','The new planting of pines covered the hillside.','Planting began after the soil warmed.','The farmer planted each seed by hand.','new planting 可指一片人工种植的树木。',1,'context'),q('Which verb is the base of planting?','plant','plan','plate','planting 由动词 plant 加 -ing 构成。',1,'word-formation')]);
P('plantlike','Plantlike combines plant with -like, “similar to”; it describes a form, growth pattern, or life style resembling a plant.',C('plantlike.s1','像植物的','The deep-sea organism has a plantlike shape, but it moves slowly toward food instead of making its own energy from sunlight.','这种深海生物外形像植物，但它会慢慢移动去觅食，而不是靠阳光制造能量。','The organism has a plantlike shape / but moves toward food / instead of using sunlight.','plantlike 表示形态或特征像植物，不等于它在分类上真是植物。','外形相似但行为和营养方式不同。'),M('The animal was called plantlike because it was an ordinary flying bird with no plant-shaped features.','The animal was called plantlike because its branching body resembled a small plant.','没有植物状特征的普通飞鸟不能说明外形像植物。','meaning'),[q('What made the deep-sea organism plantlike?','its shape resembled a plant','it was a flowering tree rooted in a garden','it was a wooden serving tray','它的外形像植物。'),q('What does plantlike mean?','similar in form or character to a plant','made entirely from a living plant','a device used to plant seeds','plantlike 指像植物的，并不必然属于植物。',1,'meaning'),q('Which object looks plantlike?','a branching coral-shaped model','a smooth metal ball with no branches','a paper court filing','分枝状模型外形类似植物。',1,'context'),q('What does -like mean in plantlike?','similar to or resembling','the plural of','a person who studies','-like 表示“像……的”。',1,'word-formation')]);
P('plants','Plants is the plural of plant, a word from Latin planta, “shoot or cutting”; it refers to living organisms such as trees, flowers, and grasses.',C('plants.s1','植物（复数）','Native plants along the riverbank provide shade and shelter for insects and small birds.','河岸边的本地植物为昆虫和小鸟提供遮荫和庇护。','Native plants along the riverbank / provide shade and shelter / for insects and small birds.','plants 是 plant 的复数，指多种植物或多个植物个体。','本地植物形成栖息环境。'),M('The botanist counted three plants, but the report listed only one tree and no other living vegetation.','The botanist counted three plants: a tree, a fern, and a flowering herb.','只记录一棵树且没有其他植被，与数出三种植物不符。','plural'),[q('What do riverbank plants provide?','shade and shelter for small wildlife','a wooden plank for a cart','a platform for train passengers','河岸植物为小动物提供遮荫和庇护。'),q('What does plants mean?','living things such as trees, flowers, and grasses','factories that make garden tools','only the seeds inside a flower','plants 指树木、花草等植物。',1,'meaning'),q('Which list contains plants?','a fern, a rose, and a young tree','a bird, a fish, and a mouse','a plate, a plank, and a platform','蕨、玫瑰和树苗都是植物。',1,'context'),q('What is the singular form of plants?','plant','planted','planting','plants 是 plant 的复数形式。',1,'grammar')]);
P('plaque','Plaque came from French plaque, “metal plate or tablet,” perhaps through Flemish; it can mean a commemorative plate or a thin bacterial deposit on teeth.',[C('plaque.s1','牌匾；纪念牌','A bronze plaque beside the entrance records the date when the community clinic first opened.','入口旁的铜牌记录了社区诊所首次开业的日期。','A bronze plaque beside the entrance / records the date / the clinic first opened.','plaque.s1 指固定在墙面或建筑上的文字牌。','牌匾上刻有开业信息。'),C('plaque.s2','牙菌斑','The hygienist showed Amir how to brush along the gumline where plaque collects.','牙科保健师向阿米尔演示如何沿牙龈线刷牙，因为牙菌斑会在那里积聚。','The hygienist showed Amir / how to brush along the gumline / where plaque collects.','plaque.s2 指附着在牙齿上的细菌薄膜。','牙菌斑积聚于牙龈边缘。')],M('The dentist called the bacteria-free bronze sign on the clinic wall dental plaque.','The dentist called the bacterial film collecting on the teeth plaque.','墙上的纪念牌是 commemorative plaque，牙科 plaque 则是细菌薄膜。','confusable'),[q('What information does the bronze plaque display?','the date the clinic opened','how to brush teeth','the latest blood platelet count','牌匾记录诊所开业日期。',1,'context'),q('Where does dental plaque collect?','along the teeth near the gumline','on a bronze wall sign','inside a planetarium dome','牙菌斑会在牙齿和牙龈边缘积聚。',2,'context'),q('What is plaque in the dental sense?','a thin film of bacteria on teeth','a flat memorial tablet fixed to a wall','a small plate used for serving food','牙科 plaque 指牙齿上的细菌薄膜。',2,'meaning'),q('Which source language contributed plaque?','French plaque, “metal plate”','Greek plasma, “blood liquid”','Latin plantatio, “planting”','plaque 源自法语中表示金属牌片的词。',1,'word-formation')]);
P('plash','Plash as a noun is Old English plæsc, “puddle,” probably imitative; related uses describe a light splash or the soft sound of water striking.',[C('plash.s1','浅水坑；轻柔水声','A shallow plash beside the path reflected the reeds after the brief shower.','短暂阵雨后，路边浅浅的水坑映出了芦苇。','A shallow plash beside the path / reflected the reeds / after the brief shower.','plash.s1 可指浅水坑，也可指轻微击水声。','雨后小水坑映出岸边植物。'),C('plash.s2','轻轻溅水','The children plashed at the lake’s edge without splashing water onto the picnic blankets.','孩子们在湖边轻轻拨水，没有把水溅到野餐毯上。','The children plashed at the lake’s edge / without splashing water / onto the blankets.','plash.s2 作动词指水轻轻溅起或人在水中轻轻嬉水。','动作轻柔，未造成大水花。')],M('The children plashed by diving from the roof and sending a violent wave across the dry playground.','The children plashed gently at the lake’s edge, making small splashes.','轻柔拨水不是猛烈跳水或掀起巨浪。','meaning'),[q('What did the shallow plash reflect?','the reeds beside the path','a bronze clinic sign','a planet in a telescope','路边浅水坑映出了芦苇。'),q('What does plash mean as a verb?','splash softly or dabble in water','cover a wall with plaster','file a formal complaint','plash 作动词表示轻轻溅水。',2,'meaning'),q('Which sound is a plash?','a soft patter as a small wave reaches shore','a loud crash as a metal plate falls','a chorus of applause in a theatre','小浪轻拍岸边发出 plash 声。',1,'context'),q('What is the possible source of the puddle noun plash?','Old English plæsc, perhaps imitative','Greek platypous, “flat-footed”','French plateau, “table-land”','名词 plash 源于古英语 plæsc，可能是拟声词。',1,'word-formation')]);
P('plasma','Plasma comes from Greek plasma, “something molded or formed,” from plassein, “mold”; in science it names the liquid part of blood or an ionized gas.',[C('plasma.s1','血浆','After the blood cells were separated in the laboratory, the pale plasma remained in the upper part of the tube.','实验室分离血细胞后，淡黄色血浆留在试管上层。','After the blood cells were separated / the pale plasma remained / in the upper part of the tube.','plasma.s1 是悬浮血细胞的液体部分。','离心后血浆位于试管上层。'),C('plasma.s2','等离子体；电浆','Inside the fusion chamber, intense heat turned the gas into plasma containing free electrons and ions.','聚变室内的高温把气体变成含自由电子和离子的等离子体。','Inside the fusion chamber / intense heat turned the gas into plasma / containing free electrons and ions.','plasma.s2 是由自由电子和离子组成的电离气体。','电离气体具有带电粒子。')],M('The lab labeled the blood-cell-free liquid as plasma, although it was a solid metal sheet with no liquid.','The lab labeled the pale liquid left above the blood cells as plasma.','血浆是血液液体部分，不是固体金属片。','meaning'),[q('Where did the pale plasma remain after separation?','in the upper part of the blood tube','under the wooden plank','on the planetarium ceiling','血细胞分离后血浆留在试管上层。',1,'context'),q('What particles are present in plasma in the fusion chamber?','free electrons and ions','red petals and pollen','only neutral wooden fibers','等离子体含有自由电子和离子。',2,'context'),q('What does plasma.s1 name?','the liquid part of blood','a gas with free charged particles','a wall coating mixture','血浆是血液中的液体部分。',1,'meaning'),q('Which Greek verb is the origin of plasma?','plassein, “to mold”','plassein, “to clap”','plangere, “to lament”','plasma 源自希腊语 plassein，意为“塑形”。',1,'word-formation')]);
P('plaster','Plaster came from Greek emplastron through Latin and French; it can be a wall-coating mixture, spread something thickly, or a small dressing stuck over a cut.',[C('plaster.s1','灰泥；石膏','The workers smoothed fresh plaster over the cracked interior wall before painting it.','工人先把新灰泥抹平覆盖在开裂的内墙上，然后再刷漆。','The workers smoothed fresh plaster / over the cracked wall / before painting it.','plaster.s1 指涂在墙面上的软质灰泥或石膏混合物。','墙面先抹灰再涂漆。'),C('plaster.s2','厚厚涂抹；覆盖','The children plastered the cardboard model with blue paper to make it look like the ocean.','孩子们把蓝纸厚厚贴在纸板模型上，让它看起来像海洋。','The children plastered the model / with blue paper / to make it look like the ocean.','plaster.s2 作动词，表示把某物厚厚覆盖或涂抹在表面。','模型表面被蓝纸覆盖。'),C('plaster.s3','创可贴；小块敷料','She put a plaster over the small cut on her finger before returning to the kitchen.','她在手指的小伤口上贴了创可贴，然后回到厨房。','She put a plaster over the small cut / on her finger / before returning to work.','plaster.s3 在英式英语中可指贴在小伤口上的敷料。','敷料盖住手指伤口。')],M('The nurse put a plaster beside the cut without covering or protecting the injured skin.','The nurse put a plaster over the cut to protect the injured skin.','敷料应盖住伤口，放在旁边不能保护伤处。','meaning'),[q('What did workers smooth over the cracked wall?','a lime-based wall coating','a blood component','a flat plate for dinner','工人把灰泥抹在墙面上。',1,'context'),q('How did the children plaster the model?','they covered it thickly with blue paper','they carved a wooden plank into it','they placed a blood sample above it','孩子们用蓝纸覆盖纸板模型。',2,'context'),q('What did she place on the small cut?','a small adhesive dressing','a wall coating mixture','a metal serving dish','这里 plaster 指伤口敷料。',3,'meaning'),q('Which source word is related to plaster?','Greek emplastron, “salve or plaster”','Greek planētēs, “wanderer”','Latin plaudite, “applaud”','plaster 源自希腊语 emplastron。',1,'word-formation')]);
P('plastic','Plastic comes from Greek plastikos, “fit for molding,” from plassein, “mold”; it can name a moldable synthetic material or describe something moldable or artificial.',[C('plastic.s1','塑料','The reusable plastic container is light enough for a child to carry but strong enough to protect the lunch.','这个可重复使用的塑料容器足够轻，孩子能拿动，也足够结实，可以保护午餐。','The reusable plastic container / is light enough to carry / and strong enough to protect lunch.','plastic.s1 指可加工成多种形状的合成材料。','容器由轻而结实的塑料制成。'),C('plastic.s2','塑料制的','The museum moved the plastic chairs outside after the storm passed.','暴风雨过后，博物馆把塑料椅子搬到了室外。','The museum moved the plastic chairs / outside / after the storm passed.','plastic.s2 作形容词表示“由塑料制成”。','椅子的材料是塑料。'),C('plastic.s3','可塑的；显得不真诚的','The young artist’s plastic clay could be reshaped, but the actor’s plastic smile seemed forced and insincere.','年轻艺术家的软陶可以重新塑形，而演员僵硬的笑容则显得勉强、不真诚。','The artist’s plastic clay could be reshaped / but the actor’s plastic smile / seemed forced.','plastic.s3 可指易于塑造，也可比喻显得人造或不真诚。','句中分别展示可塑材料和做作表情。')],M('The clay was called plastic because it was too rigid to shape, while the actor’s smile was natural and sincere.','The clay was plastic enough to shape, while the actor’s smile looked artificial.','无法塑形的材料不具可塑性；自然真诚的笑容也非“做作”。','meaning'),[q('What quality made the container useful?','it was light yet strong','it was made of blood plasma','it could not be carried by a child','塑料容器轻而结实。'),q('What does plastic describe in “plastic chairs”?','chairs made of plastic material','chairs that can fly through the air','chairs covered with plaster','plastic chairs 指塑料椅子。',2,'meaning'),q('What does plastic clay do?','it can be reshaped','it becomes an ionized gas','it forms a plaque on teeth','可塑软陶能够重新塑形。',3,'context'),q('Which Greek verb gave rise to plastic?','plassein, “to mold”','plangere, “to lament”','plaudere, “to clap”','plastic 源于表示“塑形”的希腊语 plassein。',1,'word-formation')]);
P('plasticity','Plasticity is formed from plastic plus -ity; it names the capacity of a material or system to be molded, changed, or reorganized.',C('plasticity.s1','可塑性；可改变性','The rehabilitation study measured the brain’s plasticity by tracking how practice changed the patients’ neural responses.','康复研究通过追踪练习如何改变患者的神经反应来测量大脑的可塑性。','The study measured the brain’s plasticity / by tracking how practice changed / neural responses.','plasticity 指被塑造、改变或重组的能力。','练习后神经反应发生变化，体现适应能力。'),M('The report called the material’s plasticity high even though it could not be reshaped or altered under any conditions.','The report called the material’s plasticity high because it could be reshaped without breaking.','完全不能改变或塑形的材料没有可塑性。','meaning'),[q('What did the rehabilitation study track?','changes in neural responses after practice','a decline in platelet counts','the width of a dinner plate','研究追踪练习后的神经反应变化。'),q('What is plasticity?','the capacity to be molded or reorganized','the quality of being made from metal','a repeated remark with no new information','plasticity 指可塑造或重组的能力。',1,'meaning'),q('Which example shows plasticity?','a brain adapting its response after repeated training','a metal plate remaining unchanged when bent','a mountain keeping a fixed elevation','训练后大脑调整反应体现可塑性。',1,'context'),q('Which adjective is the base of plasticity?','plastic','plausible','planetary','plasticity 由 plastic 加名词后缀 -ity 构成。',1,'word-formation')]);
P('plate','Plate came through Old French from Medieval Latin plata, “flat sheet of metal”; it can be a dish, a flat sheet or layer, a portion of food, or the verb “cover with a thin metal layer.”',[C('plate.s1','盘子；碟子','She placed the warm bread on a clean plate before setting it beside the soup.','她把热面包放在干净的盘子上，再把盘子放到汤旁边。','She placed the warm bread / on a clean plate / beside the soup.','plate.s1 指用来盛放食物的扁平餐具。','面包盛在盘子里。'),C('plate.s2','金属片；岩层','A steel plate covered the narrow opening in the floor until the repair crew arrived.','维修队到达前，一块钢板盖住了地板上的窄洞。','A steel plate covered the opening / in the floor / until the repair crew arrived.','plate.s2 可指平坦的金属片或地质板块。','钢板平铺覆盖地面开口。'),C('plate.s3','一盘；一份食物','The lunch special includes a plate of roasted vegetables and rice.','午餐特餐包括一份烤蔬菜和米饭。','The lunch special includes / a plate of roasted vegetables and rice.','plate.s3 可按装在一个盘子里的量指一份食物。','菜单将蔬菜和米饭作为一份供应。'),C('plate.s4','镀金属；覆盖金属层','The workshop plated the brass handle with nickel to make its surface more resistant to wear.','工坊给黄铜把手镀上一层镍，使表面更耐磨。','The workshop plated the brass handle / with nickel / to resist wear.','plate.s4 作动词，表示在物体表面覆盖薄金属层。','镍层覆盖黄铜表面。')],M('The workshop plated the handle with nickel by leaving the brass completely bare and adding no metal coating.','The workshop plated the handle with nickel by applying a thin metal layer over the brass.','没有覆盖任何金属层就不是电镀。','meaning'),[q('Where did she put the warm bread?','on a clean dish beside the soup','on a steel sheet over a floor opening','inside a blood sample','面包放在餐盘上。',1,'context'),q('What covered the opening in the floor?','a flat steel sheet','a plate of vegetables','a layer of nickel on brass','钢板盖住了地板上的洞。',2,'context'),q('What does “a plate of vegetables” mean?','a serving of food on one dish','a geological layer under a mountain','a coating of nickel on a handle','a plate of vegetables 指一盘或一份食物。',3,'meaning'),q('What happened when the workshop plated the handle?','it covered the brass with a thin nickel layer','it served food on a flat dish','it cut the handle into a steel sheet','plate 作动词表示给物体镀上一层金属。',4,'meaning')]);
P('plateau','Plateau came from French plateau, “table-land,” from plat, “flat”; it can be a high flat area, a stage with no further rise, or the verb meaning level off.',[C('plateau.s1','高原；高地平原','The hikers crossed a broad plateau where the land stayed nearly level above the surrounding valleys.','徒步者穿过一片宽阔高原，那里地势高于周围山谷且基本平坦。','The hikers crossed a broad plateau / where the land stayed nearly level / above the valleys.','plateau.s1 指海拔较高且相对平坦的广大地区。','高地地形平坦并高于周边山谷。'),C('plateau.s2','停滞期；平稳阶段','After rapid growth in its first year, the project reached a plateau and added no new users for several months.','项目第一年快速增长后进入停滞期，数月没有新增用户。','After rapid growth / the project reached a plateau / and added no new users.','plateau.s2 指某项指标停止上升、保持稳定的一段时期。','用户数量不再增长。'),C('plateau.s3','达到稳定水平；停滞','Sales plateaued after the holiday rush, remaining steady through the quiet winter months.','节日促销结束后销量趋于平稳，在冬季淡季一直保持稳定。','Sales plateaued after the holiday rush / remaining steady / through the winter.','plateau.s3 作动词，表示增长停止并维持在同一水平。','销量停止上升并保持稳定。')],M('After the holiday rush, sales plateaued and continued doubling every week without any leveling off.','After the holiday rush, sales plateaued and stayed at roughly the same level.','持续翻倍说明销量仍在增长，不是进入平台期。','meaning'),[q('What kind of land did the hikers cross?','high, broad, relatively level land','a narrow valley far below the hills','a raised platform beside train tracks','徒步者穿过高而平坦的高原。',1,'context'),q('What happened to the project after its first year?','growth stopped and user numbers stayed level','user numbers doubled every week','the project became a mountain range','项目新增用户进入停滞期。',2,'context'),q('What does plateau mean as a verb?','stop increasing and remain at a level','rise steeply without slowing','cover a surface with nickel','plateau 作动词表示停止增长并保持稳定。',3,'meaning'),q('What does French plateau literally suggest?','table-land or flat surface','a tiny blood cell','enthusiastic applause','plateau 源自表示桌状平坦地形的法语词。',1,'word-formation')]);
P('platelet','Platelet was formed from plate plus the diminutive suffix -let; it names a small blood component that gathers at wounds and helps form clots.',C('platelet.s1','血小板','The nurse explained that platelets help seal a small cut by gathering where the blood vessel is damaged.','护士解释说，血小板会聚集在血管受损处，帮助封住小伤口。','The nurse explained / platelets gather where a vessel is damaged / to help seal a cut.','platelet 是血液中的小细胞成分，参与止血和凝血。','血小板聚集于损伤处帮助凝血。'),M('The doctor said platelets stopped the bleeding by preventing all clotting at the wound.','The doctor said platelets helped stop the bleeding by gathering and supporting a clot.','阻止凝血不会止血；血小板有助于形成凝块。','meaning'),[q('Where do platelets gather?','where a blood vessel is damaged','on the wall of a planetarium','inside a wooden serving platter','血小板聚集在血管受损处。'),q('What do platelets help do?','form a clot that seals a wound','carry oxygen as the liquid part of blood','coat a handle with nickel','platelets 帮助形成凝块止血。',1,'meaning'),q('Which part of blood is a platelet?','a small component involved in clotting','the pale fluid that suspends blood cells','a large flat wall sign','platelet 是参与凝血的小血液成分。',1,'context'),q('What does -let contribute in platelet?','the idea of something small','the idea of a place for stars','the idea of enthusiastic approval','-let 在 platelet 中表示小型的东西。',1,'word-formation')]);
P('platelike','Platelike combines plate with -like, “resembling”; it describes a thin, flat form similar to a plate.',C('platelike.s1','像薄板的；盘状的','The fossil contains a platelike shell fragment that is broad, flat, and only a few millimeters thick.','这块化石里有一片盘状贝壳碎片，形状宽而扁，厚度只有几毫米。','The fossil contains a platelike shell fragment / broad and flat / only a few millimeters thick.','platelike 描述薄而平、形似板片或盘子的形状。','贝壳碎片扁平且很薄。'),M('The object was platelike because it was a round, thick sphere with no flat surface.','The object was platelike because it was broad, thin, and flat.','厚实的球体没有薄平板状特征。','meaning'),[q('What shape was the shell fragment?','broad, flat, and only a few millimeters thick','round and thick like a ball','long and narrow like a stalk','化石碎片扁平且很薄。'),q('What does platelike mean?','having the shape of a thin, flat plate','made from blood plasma','likely to cause a plague','platelike 指形状像薄平板。',1,'meaning'),q('Which object is platelike?','a thin flat shard of shell','a thick round marble','a narrow leaf stem','薄而平的贝壳碎片呈盘片状。',1,'context'),q('What does -like mean in platelike?','resembling or similar to','covered with a metal layer','the plural of plate','-like 表示“像……的”。',1,'word-formation')]);
P('platform','Platform came from French plateforme, literally “flat form,” from plat “flat” plus forme “form”; it can be a raised surface, a train-waiting area, political principles, or a computer base.',[C('platform.s1','平台；高台','The speaker stepped onto the raised platform so everyone in the hall could see her demonstration.','演讲者走上高台，让大厅里的每个人都能看到她的演示。','The speaker stepped onto the raised platform / so everyone in the hall / could see her.','platform.s1 指高出地面、供人站立的平坦表面。','高台让演示更容易被看见。'),C('platform.s2','站台','Passengers waited on the platform until the northbound train arrived.','乘客们在站台上等到北行列车进站。','Passengers waited on the platform / until the northbound train / arrived.','platform.s2 指铁路轨道旁旅客候车的区域。','乘客在火车站台候车。'),C('platform.s3','政纲；纲领','The candidate’s platform promises to expand public transit and publish city spending online.','候选人的政纲承诺扩建公共交通，并在线公开市政支出。','The candidate’s platform promises / to expand public transit / and publish city spending.','platform.s3 指政党或候选人的主要目标和政策主张。','平台内容列出竞选政策。'),C('platform.s4','计算机平台','The new learning app runs on a platform that supports both phones and classroom computers.','这款新的学习应用运行在一个同时支持手机和教室电脑的平台上。','The learning app runs on a platform / that supports phones / and classroom computers.','platform.s4 指其他软件或程序赖以运行的计算机系统基础。','应用程序依托跨设备系统运行。')],M('The candidate’s platform was a wooden railway surface used only for waiting beside train tracks.','The candidate’s platform set out policy aims for transit and public spending.','候选人的 platform 是政治纲领，不是铁路站台。','confusable'),[q('Why did the speaker stand on the raised platform?','so the hall could see her demonstration','to wait for a northbound train','to run a phone application','高台使大厅观众能看见演示。',1,'context'),q('Where did passengers wait?','beside the railway tracks','on the candidate’s policy paper','inside a blood vessel','乘客在铁路站台候车。',2,'context'),q('What is the candidate’s platform?','the main policies and aims she supports','a raised wooden stage in the station','the software system used by a phone','候选人的 platform 指其政纲。',3,'meaning'),q('What does platform mean in the app example?','a computer system on which software runs','a stage raised above the floor','a statement of campaign policies','应用运行所依托的系统叫 platform。',4,'meaning')]);
P('platinum','Platinum entered English from Spanish platina, a diminutive of plata, “silver”; it is the dense, chemically unreactive precious metal with atomic number 78.',C('platinum.s1','铂；白金','The laboratory used a platinum electrode because the metal resists corrosion during the experiment.','实验室使用铂电极，因为这种金属在实验中耐腐蚀。','The laboratory used a platinum electrode / because the metal / resists corrosion.','platinum 是化学性质稳定、密度较大的贵金属元素。','铂的耐腐蚀性适用于电极。'),M('The jeweler identified the ring as platinum because it was a light, reactive gas that corroded quickly.','The jeweler identified the ring as platinum, a dense metal that resists corrosion.','platinum 是稳定的固体贵金属，不是轻质活泼气体。','meaning'),[q('Why did the lab choose a platinum electrode?','it resists corrosion','it dissolves immediately in water','it is a soft flower petal','铂耐腐蚀，适合实验电极。'),q('Which element is platinum?','a dense precious metal, element 78','a gas made of free electrons and ions','a small cell that helps blood clot','platinum 是第78号贵金属元素。',1,'meaning'),q('Which object could be made of platinum?','a corrosion-resistant laboratory electrode','a disposable paper label','a dried plant stem','耐腐蚀的实验电极可能由铂制成。',1,'context'),q('Which Spanish word contributed to platinum?','platina, a diminutive of plata “silver”','planta, “a shoot”','plañir, “to lament”','platinum 来自西班牙语 platina，与 plata“银”有关。',1,'word-formation')]);
P('platitude','Platitude came from French platitude, “flatness,” based on plat, “flat”; it means a dull, overused remark presented as if it were insightful.',C('platitude.s1','陈词滥调；空话','When the staff asked how the policy would change, the director offered the platitude “change is always difficult” and no details.','员工询问政策将如何改变时，主管只说了“改变总是困难的”这句空话，没有提供细节。','The director offered the platitude / “change is always difficult” / but gave no details.','platitude 指重复多次、内容平淡且缺乏实际信息的话。','套话没有回答具体问题。'),M('The director gave a platitude by presenting a new, detailed repair schedule that answered every question.','The director gave a platitude by repeating “change is always difficult” without explaining the policy.','具体且有信息的新方案不是空泛陈词。','meaning'),[q('What did the director say instead of explaining the policy?','“change is always difficult”','the exact dates and steps of the new policy','the location of the train platform','主管只给出一句常见套话。'),q('What is a platitude?','an overused, dull remark with little new information','a thin bacterial film on teeth','an elevated flat area of land','platitude 指陈词滥调或空话。',1,'meaning'),q('Which sentence is a platitude?','“We must work together to make progress,” with no concrete plan','“The repair begins Monday at 8 a.m. and ends Tuesday.”','“The platelet count fell from 220 to 190.”','没有具体方案的泛泛口号是空话。',1,'context'),q('What image lies behind platitude’s origin?','flatness or dullness','a flat-footed animal','a metal plate used in a lab','platitude 的词源与“平、乏味”有关。',1,'word-formation')]);
P('platitudinous','Platitudinous was formed from platitude plus -ous; it describes speech or writing full of dull, overused remarks.',C('platitudinous.s1','充满陈词滥调的','The platitudinous review called the film “a journey of emotions” but never discussed its acting, script, or images.','这篇充满陈词滥调的影评把电影称为“情感之旅”，却完全没有讨论表演、剧本或画面。','The platitudinous review called the film / “a journey of emotions” / but discussed no details.','platitudinous 形容内容充满空泛、听腻了的套话。','评论没有具体分析，只堆叠常见表达。'),M('The review was platitudinous because it supplied original scene-by-scene evidence and precise analysis.','The review was platitudinous because it relied on vague, familiar phrases instead of specific analysis.','具体新颖的逐场分析并非陈词滥调。','meaning'),[q('What was missing from the platitudinous review?','specific discussion of acting, script, and images','a repeated phrase about emotions','a picture of the film’s poster','影评缺少具体分析。'),q('What does platitudinous mean?','full of dull, overused remarks','made from a dense precious metal','similar in shape to a flat plate','platitudinous 指充斥陈词滥调的。',1,'meaning'),q('Which paragraph is platitudinous?','one that says “stories touch our hearts” repeatedly without examples','one that compares two scenes using specific evidence','one that lists the actors and release date','反复使用泛泛套话而无例证的段落很空洞。',1,'context'),q('Which noun is the base of platitudinous?','platitude','platelet','platform','platitudinous 由 platitude 加 -ous 构成。',1,'word-formation')]);
P('platter','Platter came from Anglo-French plater and Old French plate; it is a large, shallow serving dish, especially for food shared at a meal.',C('platter.s1','大浅盘；大餐盘','The host arranged roasted vegetables on a platter so guests could serve themselves.','主人把烤蔬菜摆在大浅盘上，让客人自行取用。','The host arranged roasted vegetables / on a platter / so guests could serve themselves.','platter 指盛放或端上桌的大而浅的盘子。','食物供多人从大盘中取用。'),M('The host served a roast on a tiny deep cup and called it a platter for the whole table.','The host served the roast on a large, shallow platter for the whole table.','小而深的杯子不符合大浅盘的形状和用途。','meaning'),[q('Where did the host arrange the vegetables?','on a large dish for guests to share','on a tiny cup for one drink','in a blood tube','蔬菜摆在供客人分享的大盘上。'),q('What is a platter?','a large, shallow dish for serving food','a small blood cell involved in clotting','a flat raised stage for a speaker','platter 指大而浅的盛菜盘。',1,'meaning'),q('Which item would be served on a platter?','a whole roast for several guests','a single drop of medicine','a railway ticket','多人共享的整只烤肉适合放在大餐盘上。',1,'context'),q('Which word is platter historically related to?','plate','plankton','plaintive','platter 来自与 plate 有关的法语形式。',1,'word-formation')]);
P('platypus','Platypus comes from Greek platypous, literally “flat-footed,” from platys “flat” and pous “foot”; it is an Australian egg-laying mammal with a ducklike bill.',C('platypus.s1','鸭嘴兽','The platypus surfaced in the creek with a small fish held in its broad bill.','鸭嘴兽叼着一条小鱼浮出溪面，它宽阔的喙十分醒目。','The platypus surfaced in the creek / with a small fish / held in its broad bill.','platypus 是澳大利亚的单孔类哺乳动物，具有鸭嘴状口部并产卵。','水中觅食的动物特征与鸭嘴兽相符。'),M('The guide identified the platypus as a flying bird that lays no eggs and has feathers instead of fur.','The guide identified the platypus as an egg-laying mammal with a ducklike bill.','鸭嘴兽是产卵哺乳动物，不是有羽毛的飞鸟。','meaning'),[q('What did the platypus hold in its bill?','a small fish','a metal plaque','a wooden plank','鸭嘴兽叼着小鱼浮出水面。'),q('What is unusual about the platypus?','it is an egg-laying mammal with a ducklike bill','it is a bird that cannot lay eggs','it is a fish that lives only in salt water','鸭嘴兽是有鸭嘴状口部的产卵哺乳动物。',1,'meaning'),q('Where is the platypus native?','Australia','the Arctic Ocean','the French plateau','platypus 是澳大利亚动物。',1,'context'),q('What does Greek platypous literally mean?','flat-footed','wandering star','molded liquid','platypus 源自希腊语“扁平的脚”。',1,'word-formation')]);
P('plaudit','Plaudit came from Latin plaudite!, “applaud!”; it means enthusiastic approval, often expressed through applause or strong praise.',C('plaudit.s1','喝彩；称赞','The young composer received a plaudit from the orchestra after her new work premiered.','新作品首演后，年轻作曲家受到了乐团的热烈称赞。','The young composer received a plaudit / after her new work / premiered.','plaudit 指热烈的赞许或喝彩。','作品首演后乐团给予肯定。'),M('The audience gave the composer a plaudit by booing her and rejecting the performance as a failure.','The audience gave the composer a plaudit by applauding and praising the performance.','嘘声和否定表达不赞许，与 plaudit 含义相反。','meaning'),[q('What did the orchestra give the composer?','enthusiastic approval after the premiere','a court complaint about the score','a sheet of platinum','作曲家获得乐团热烈称赞。'),q('What does plaudit mean?','enthusiastic approval or applause','a dull, overused saying','a high, flat area of land','plaudit 指热烈赞许或喝彩。',1,'meaning'),q('Which response is a plaudit?','a standing ovation and strong praise','silence followed by a complaint','a report of falling platelet counts','起立鼓掌并热烈称赞是喝彩。',1,'context'),q('Which Latin expression is the source of plaudit?','plaudite!, “applaud!”','plassein, “to mold”','planctus, “lamentation”','plaudit 源自拉丁语 plaudite!。',1,'word-formation')]);
P('plausibility','Plausibility came from plausible plus -ity; it is the appearance of being believable or likely, whether or not a claim is actually true.',C('plausibility.s1','似真性；看似合理','The witness’s changing timeline weakened the plausibility of his claim that he had been home all evening.','证人不断变化的时间线削弱了他声称整晚都在家的可信度。','The changing timeline weakened / the plausibility of the claim / that he was home all evening.','plausibility 指表面上听起来可信或合理的程度，不等同于事实证据。','时间线矛盾使说法不再可信。'),M('The claim’s plausibility proved it was definitely true, even though no records or witnesses supported it.','The claim seemed plausible, but its truth remained unproven without records or witnesses.','看起来可信不等于已经证实为真。','meaning'),[q('What weakened the claim’s plausibility?','the witness kept changing his timeline','several records confirmed each hour','the witness plainly explained every detail','时间线反复变化使说法更难令人相信。'),q('What does plausibility mean?','the appearance of being believable or likely','proof that a claim is unquestionably true','a playful way of teasing a friend','plausibility 是表面上看似可信的程度。',1,'meaning'),q('Which report has plausibility but still needs checking?','a coherent account with no independent evidence yet','a statement contradicted by every timestamp','a tested result confirmed by several laboratories','连贯但未独立证实的说法看似合理，仍需核实。',1,'context'),q('Which word is the base of plausibility?','plausible','playful','plaintive','plausibility 由 plausible 加 -ity 构成。',1,'word-formation')]);
P('plausible','Plausible comes from Latin plausibilis, “worthy of approval,” from plaudere, “applaud”; it describes a claim that seems true or a person who sounds honest, though neither guarantees sincerity.',[C('plausible.s1','看似可信的；貌似合理的','The engineer offered a plausible explanation for the pressure drop, but the team still checked the faulty gauge.','工程师对压力下降给出了一个看似合理的解释，但团队仍检查了可能故障的仪表。','The engineer offered a plausible explanation / for the pressure drop / but the team checked the gauge.','plausible.s1 指听起来像真的、表面合理的说法。','解释合理但尚需验证。'),C('plausible.s2','貌似诚实可信的','The plausible salesman spoke warmly and confidently, yet the contract revealed fees he had not mentioned.','这位看起来诚恳的销售员说话亲切而自信，但合同里出现了他未提到的费用。','The plausible salesman spoke warmly / yet the contract revealed / fees he had not mentioned.','plausible.s2 可形容说话显得诚实可信的人，但表面印象未必代表真心。','亲切外表与隐藏费用形成反差。')],M('The explanation was plausible, so the team treated it as proven fact and stopped checking the faulty gauge.','The explanation was plausible, but the team checked the gauge before accepting it as fact.','plausible 表示看似合理，不代表已经证实。','meaning'),[q('What did the engineer explain?','why the pressure had dropped','why the salesman hid fees','why the play ended early','解释针对压力下降。',1,'context'),q('What did the contract reveal about the plausible salesman?','he had not mentioned some fees','he had tested the pressure gauge','he had written a stage play','合同显示他漏说了一些费用。',2,'context'),q('What does plausible mean in “a plausible explanation”?','seeming likely to be true','certainly proven by evidence','unpleasant to experience','plausible 表示看起来可能为真。',1,'meaning'),q('What caution applies to a plausible person?','sounding honest does not guarantee sincerity','a confident manner proves all claims','a pleasant voice means no fee is hidden','听起来可信不等于一定诚实。',2,'meaning')]);
P('plausibly','Plausibly is the adverb from plausible plus -ly; it means in a way that appears believable or likely.',C('plausibly.s1','貌似合理地；看似可信地','The missing key could plausibly have fallen behind the cabinet, so the caretaker searched there first.','钥匙很可能掉到了柜子后面，因此管理员先在那里寻找。','The missing key could plausibly have fallen / behind the cabinet / so the caretaker searched there first.','plausibly 修饰可能性判断，表示一种合理但未证实的解释。','柜子后方是可信的遗失位置，但尚未找到。'),M('The key plausibly fell behind the cabinet, and the caretaker treated that guess as certain proof without searching.','The key could plausibly have fallen behind the cabinet, so the caretaker searched there to check.','plausibly 表示看似可能，并非确定事实。','meaning'),[q('Where might the key plausibly have fallen?','behind the cabinet','inside a signed court judgment','into a planet’s orbit','管理员认为钥匙可能掉在柜子后。'),q('What does plausibly mean?','in a way that seems believable or likely','in a way that is guaranteed to be true','in a way that causes friendly teasing','plausibly 表示看起来可能或合理地。',1,'meaning'),q('Which explanation is plausible rather than proven?','the key may have slipped into a bag during packing','a video clearly shows the key being placed on the desk','the caretaker holds the key in her hand','“可能掉进包里”是合理猜测但仍未证实。',1,'context'),q('Which adjective is the base of plausibly?','plausible','plaintive','playful','plausibly 由 plausible 加 -ly 构成。',1,'word-formation')]);
P('play','Play comes from Old English plegan, “occupy oneself or amuse oneself”; its deepest origin is uncertain. It can mean enjoy an activity, perform music, a stage work, or act a role or have an effect.',[C('play.s1','玩耍；参加游戏','The children play chess in the library after school while they wait for their parents.','孩子们放学后在图书馆下棋，等父母来接。','The children play chess / in the library after school / while waiting for their parents.','play.s1 指参加游戏或进行娱乐活动。','下棋是孩子们的游戏活动。'),C('play.s2','演奏；播放','Nora played the cello softly, then played the recording again so the class could hear the opening.','诺拉轻轻演奏大提琴，随后又播放了一遍录音，让全班听开头部分。','Nora played the cello softly / then played the recording again / for the class.','play.s2 可指演奏乐器，也可指播放录好的声音。','同一语境展示演奏和播放两种用法。'),C('play.s3','戏剧；剧本','The school’s new play tells the story of a botanist who discovers a rare flower.','学校的新剧讲述了一位植物学家发现稀有花朵的故事。','The school’s new play / tells the story / of a botanist discovering a rare flower.','play.s3 作名词指写来在舞台上演出的故事或戏剧。','故事将由学校剧团搬上舞台。'),C('play.s4','饰演；起作用','Maya will play the judge in the courtroom scene, while timing will play a major role in the final decision.','玛雅将在法庭场景中饰演法官，而时机将在最终决定中起重要作用。','Maya will play the judge / while timing will play a major role / in the final decision.','play.s4 可指饰演角色，也可指在局势中发挥作用。','句中分别体现扮演和产生影响。')],M('Nora played the cello by refusing to touch the instrument, and the school announced its new play as a real court verdict.','Nora played the cello for the class, and the school announced a stage play about a botanist.','不接触乐器就没有演奏；戏剧也不是法院判决。','meaning'),[q('What game did the children play after school?','chess','a stage verdict','a cello recording','孩子们在图书馆下棋。',1,'context'),q('What did Nora play for the class?','the cello and a recording','a judge in the school garden','a botanist’s legal plea','她先演奏大提琴，再播放录音。',2,'context'),q('What is the school’s new play?','a stage story about a botanist','a game of chess in the library','a recording of a cello lesson','school play 指舞台剧。',3,'meaning'),q('What does “play the judge” mean in the scene?','act the role of the judge','play a game against the judge','make the judge hear a recording','play the judge 意为饰演法官。',4,'meaning')]);
P('play area','Play area is the transparent compound play + area; it means a designated place where children can play.',C('play area.s1','游乐区；儿童活动区','The café added a fenced play area where toddlers could use the slide while their parents sat nearby.','咖啡馆增设了围起来的儿童活动区，幼儿可以玩滑梯，父母则坐在附近。','The café added a fenced play area / where toddlers could use the slide / while parents sat nearby.','play area 指专门供儿童玩耍的区域。','围栏和滑梯标明这是儿童活动区。'),M('The café labeled a locked storage closet with no toys or room to move as its play area.','The café labeled the fenced space with a slide as its play area.','没有游玩空间或设施的上锁储藏室不是儿童活动区。','meaning'),[q('What could toddlers do in the café’s play area?','use the slide','wait for a train','read a court verdict','幼儿可以在活动区玩滑梯。'),q('What is a play area?','a place where children can play','a room where a play is performed for an audience','a part of a computer system','play area 指儿童玩耍的地方。',1,'meaning'),q('Which place is a play area?','a safe yard with swings for children','a locked supply closet','a railway platform with no play equipment','带秋千的儿童安全院子是活动区。',1,'context'),q('What does area contribute to play area?','a place or region','a person who plays music','a stage story','area 表示区域或地方。',1,'word-formation')]);
P('player','Player is formed from play plus agent suffix -er; it can mean a person in a sport, or someone who performs music or acts.',[C('player.s1','运动员；参赛者','The player passed the ball to her teammate before the defender could block the shot.','防守队员拦截前，这名运动员把球传给了队友。','The player passed the ball / to her teammate / before the defender blocked the shot.','player.s1 指参加体育运动或比赛的人。','球员传球并试图得分。'),C('player.s2','演奏者；演员','The flute player rehearsed the final passage while the young actor learned his lines backstage.','长笛演奏者排练最后一段时，年轻演员在后台背台词。','The flute player rehearsed the passage / while the actor / learned his lines backstage.','player.s2 可指演奏乐器的人，也可指演员。','音乐家与演员分别体现第二义。')],M('The basketball player was the person who played the flute backstage, while the flute player passed the ball in the match.','The basketball player passed the ball, while the flute player rehearsed backstage.','句子把运动员和乐器演奏者的角色混淆。','confusable'),[q('What did the player pass?','the ball to a teammate','a flute to the judge','a stage script to the defender','运动员把球传给队友。'),q('What was the flute player rehearsing?','the final passage of music','a basketball defense','the café play area','长笛演奏者排练乐曲末段。',2,'context'),q('Who is a player in sports?','a person taking part in a game','a person who only watches the match','the ball used in the match','player.s1 指参加体育比赛的人。',1,'meaning'),q('Which can also be a player?','an actor performing a role','a seat reserved for a judge','a written request for help','演员也可称 player。',2,'meaning')]);
P('playful','Playful is formed from play plus -ful; it describes lively fun or friendly teasing rather than serious hostility.',C('playful.s1','爱玩的；顽皮的；打趣的','Her playful note teased her brother about his mismatched socks but ended with an invitation to lunch.','她在便条中开玩笑地打趣哥哥袜子不配套，但最后邀请他一起吃午饭。','Her playful note teased her brother / about mismatched socks / but ended with an invitation.','playful 可形容轻松爱玩的行为或友善逗趣的语气。','打趣是善意的，且表达亲近。'),M('His playful joke was intended to humiliate his coworker and made her afraid to return to the office.','His playful joke gently teased his coworker, who laughed and joined the conversation.','带有羞辱和恐吓目的的行为不是轻松友善的逗趣。','meaning'),[q('What did the playful note tease her brother about?','his mismatched socks','his court plea','his cello recording','便条开玩笑地提到袜子不配套。'),q('What does playful mean?','lively, fun, or gently teasing','severe and intended to frighten','likely to be true based on evidence','playful 指活泼有趣或善意打趣。',1,'meaning'),q('Which comment is playful?','“Those socks are auditioning for two different teams!”','“You should be afraid to come back tomorrow.”','“The defendant entered a not-guilty plea.”','第一句是轻松友善的玩笑。',1,'context'),q('Which noun is the base of playful?','play','plaint','plaza','playful 由 play 加 -ful 构成。',1,'word-formation')]);
P('playground','Playground is formed from play + ground; it first meant land set aside for open-air recreation, especially at a school, and can also mean a place where an activity thrives.',[C('playground.s1','操场；游乐场','The school playground has a climbing frame, a running track, and shaded benches for children.','学校操场有攀爬架、跑道和供孩子休息的遮阴长椅。','The school playground has a climbing frame / a running track / and shaded benches.','playground.s1 指供儿童户外玩耍的场地或带设施的地方。','场地配有儿童游乐和活动设施。'),C('playground.s2','活动场所；天地','For amateur astronomers, the desert has become a playground for testing portable telescopes under dark skies.','对业余天文学家来说，沙漠已成为在黑暗天空下测试便携望远镜的天地。','For amateur astronomers / the desert has become a playground / for testing portable telescopes.','playground.s2 可比喻某类活动自由开展的地方。','沙漠为天文观测活动提供了适宜环境。')],M('The school called the locked boiler room with no equipment or play space its playground.','The school called the open yard with climbing frames and benches its playground.','不能进入且无法活动的锅炉房不是游乐场。','meaning'),[q('What equipment is in the school playground?','a climbing frame and running track','a portable telescope only','a train platform','学校操场有攀爬架和跑道。',1,'context'),q('What is the desert a playground for?','testing portable telescopes','children using the school slide','filing a legal plea','沙漠成为测试望远镜的活动天地。',2,'context'),q('What does playground.s1 mean?','an outdoor place where children play','a court where legal cases are heard','a theatre that projects stars','playground.s1 指儿童户外玩耍的场所。',1,'meaning'),q('What is a “playground for innovation”?','a place where innovation can develop freely','a locked room that prevents experiments','a toy made for young children','这里 playground 比喻创新活动的空间。',2,'meaning')]);
P('playhouse','Playhouse combines play with house; the source entry gives the combined sense of a small theatre or a house where children play.',[C('playhouse.s1','小剧场；儿童游戏屋','The touring company performed its comedy at a neighborhood playhouse, while the children kept toy dishes in their backyard playhouse.','巡演剧团在社区小剧场演出，而孩子们把玩具餐具放在后院的儿童游戏屋里。','The touring company performed its comedy / at a neighborhood playhouse / while children played in their backyard playhouse.','playhouse 的 source entry 将小剧场与儿童玩耍的小屋合列为一个义项。','句中前一个 playhouse 是演出场所，后一个是儿童游戏屋，二者均属原词条列出的含义。')],M('The children called their backyard playhouse a courthouse where judges held legal trials.','The children used their backyard playhouse as a small house for pretend games.','儿童游戏屋不是法院；错误句把玩耍场所误说成法律审判机构。','meaning'),[q('Where did the touring company perform its comedy?','at a small neighborhood theatre','inside a courthouse','on a train platform','巡演剧团在社区小剧场演出。',1,'context'),q('What did the children keep in their backyard playhouse?','toy dishes','theatre tickets','legal files','孩子们把玩具餐具放在游戏屋里。',1,'context'),q('Which meaning is included in the source entry for playhouse?','a small theatre or a house where children play','a courthouse for legal trials','a large outdoor sports stadium','playhouse 的词条义项是小剧场或儿童玩耍的小屋。',1,'meaning'),q('Which compound forms playhouse?','play + house','plea + house','plait + house','playhouse 由 play 与 house 复合构成。',1,'word-formation')]);
P('playmate','Playmate is formed from play + mate; it means a companion in games or other play, especially another child.',C('playmate.s1','玩伴','Sam invited his next-door playmate to build a cardboard castle after school.','萨姆邀请隔壁的玩伴放学后一起搭纸板城堡。','Sam invited his next-door playmate / to build a cardboard castle / after school.','playmate 指一起玩耍的同伴，常指儿童。','两名孩子一起搭纸板城堡。'),M('Sam called the stranger who refused to play and left immediately his favorite playmate.','Sam called the neighbor who built and played with him his playmate.','拒绝一起玩且马上离开的陌生人不是共同玩耍的伙伴。','meaning'),[q('What did Sam invite his playmate to build?','a cardboard castle','a court platform','a telescope lens','两人一起搭纸板城堡。'),q('What is a playmate?','a companion who plays with someone','a person who writes stage plays','a player who competes in a professional match','playmate 指一起玩耍的伙伴。',1,'meaning'),q('Which person is a playmate?','a child who regularly plays games with a neighbor','a teacher who grades the child’s essays','a customer waiting at a station','经常一起玩游戏的邻居孩子是玩伴。',1,'context'),q('Which word combines with play to form playmate?','mate','plate','plaint','playmate 由 play 和 mate 组成。',1,'word-formation')]);
P('playroom','Playroom is formed from play + room; it means a room in a home or institution set aside for children’s toys and play.',C('playroom.s1','游戏室；儿童活动室','The family keeps a washable rug and toy bins in the playroom so the twins can build safely indoors.','这家人在游戏室里铺了可清洗的地毯并放置玩具箱，让双胞胎能在室内安全玩耍。','The family keeps a rug and toy bins / in the playroom / so the twins can build indoors.','playroom 是专门供儿童存放玩具和玩耍的房间。','房间里备有儿童游戏用品。'),M('The family called the locked room with no toys or space to move a playroom.','The family called the room with toys and space for children to play a playroom.','无玩具且不能活动的上锁房间不符合游戏室的用途。','meaning'),[q('What does the family keep in the playroom?','a washable rug and toy bins','court records and legal forms','a stage and audience seats','游戏室里有地毯和玩具箱。'),q('What is a playroom?','a room where children keep toys and play','a room where a playwright files a lawsuit','a public square surrounded by shops','playroom 指儿童玩耍和放玩具的房间。',1,'meaning'),q('Which space is a playroom?','a room set up with blocks and toys for children','a locked office with no play materials','a train platform beside the tracks','供儿童玩积木和玩具的房间是 playroom。',1,'context'),q('Which noun combines with play to form playroom?','room','ground','mate','playroom 由 play 和 room 组成。',1,'word-formation')]);
P('plaything','Plaything is play + thing; it can mean a toy, or figuratively a person treated as something to manipulate without regard for their feelings.',[C('plaything.s1','玩具','The wooden train became the toddler’s favorite plaything because its wheels still turned smoothly.','木火车的轮子转动顺畅，因此成了幼儿最喜欢的玩具。','The wooden train became the toddler’s favorite plaything / because its wheels / turned smoothly.','plaything.s1 指供玩耍的物品或玩具。','孩子把木火车当作玩具。'),C('plaything.s1','被玩弄或操纵的人','The novel portrays the apprentice as a plaything of powerful employers who changed his duties whenever it suited them.','小说把学徒描绘成有权势雇主随意摆布的人，他们想改就改他的职责。','The novel portrays the apprentice / as a plaything of powerful employers / who changed his duties at will.','plaything.s1 比喻被他人轻率操纵、未被认真对待的人。','雇主随意摆布学徒的工作。')],M('The employers treated the apprentice as a plaything by respecting his choices and allowing him to set his own duties.','The employers treated the apprentice as a plaything by changing his duties whenever it suited them.','尊重选择并让其自主与被随意摆布相反。','meaning'),[q('Why did the toddler like the wooden train?','it was a plaything with smoothly turning wheels','it was a railway platform','it was a legal plea','木火车是幼儿喜爱的玩具。',1,'context'),q('How did the employers treat the apprentice?','as someone they could manipulate at will','as a toy train with working wheels','as a playwright with full control','雇主随意更改学徒职责，把他当作可操纵的人。',1,'context'),q('What is a plaything.s1?','a toy used for play','a person who writes stage scripts','a room for keeping toys','plaything.s1 指玩具。',1,'meaning'),q('What does plaything mean figuratively?','a person treated as an object to manipulate','a respected decision-maker','a companion who shares games','比喻义指被他人随意操纵的人。',1,'meaning')]);
P('playwright','Playwright was formed from play + wright, an old word for a maker or worker; it names a person who writes plays for the theatre.',C('playwright.s1','剧作家','The playwright rewrote the final scene after actors showed that the dialogue sounded unnatural on stage.','演员指出台词在舞台上听起来不自然后，剧作家重写了最后一幕。','The playwright rewrote the final scene / after actors showed / the dialogue sounded unnatural.','playwright 指为剧院创作戏剧文本的人。','作者根据舞台排演反馈改写剧本。'),M('The playwright was the performer who merely acted in the script and never wrote or revised any of it.','The playwright wrote and revised the script that the performers acted.','只出演而不写剧本的人是演员，不是 playwright。','meaning'),[q('What did the playwright rewrite?','the final scene','the play area fence','the train platform','剧作家重写了最后一幕。'),q('What is a playwright?','someone who writes plays for the theatre','someone who only watches a play','someone who repairs a wooden playhouse','playwright 指戏剧作者。',1,'meaning'),q('Which person is a playwright?','an author creating dialogue and scenes for a stage production','an actor performing the role of a judge','a player passing a ball','写舞台对白和场景的人是 playwright。',1,'context'),q('What did the old element wright mean?','a maker or worker','a person who pleads in court','a place for children to play','wright 原指制造者或工匠。',1,'word-formation')]);
P('plaza','Plaza came through Spanish plaza from Latin platea, “courtyard or broad street”; it means a public square or, in American English, a shopping area.',[C('plaza.s1','广场','Street musicians played in the plaza while residents crossed the open square on their way to the market.','街头乐手在广场上演奏，居民穿过空地前往市场。','Street musicians played in the plaza / while residents crossed the open square / to the market.','plaza.s1 指城市里开放的公共广场。','居民和乐手使用同一处公共空地。'),C('plaza.s2','购物广场；商业区','The new plaza has a grocery store, a pharmacy, and a shared car park beside the highway.','新购物广场在公路旁设有杂货店、药房和共用停车场。','The new plaza has a grocery store / a pharmacy / and a shared car park.','plaza.s2 在美式英语中可指包含多家商店的商业区。','多家商店集中在带停车场的区域。')],M('The city called the locked private storage room with no public access a public plaza.','The city called the open square where residents gathered a public plaza.','禁止公众进入的储藏室不是公共广场。','meaning'),[q('What happened in the city plaza?','musicians played while residents crossed the square','customers shopped in an indoor playroom','a court heard a plea','市民穿过广场时有乐手演奏。',1,'context'),q('What does the new plaza beside the highway contain?','a grocery store, pharmacy, and shared car park','a single courtroom and no shops','a school playground only','购物广场聚集多家商店并有停车场。',2,'context'),q('What is a plaza.s1?','an open public square in a city','a room for children’s toys','an author of stage plays','plaza.s1 指城市公共广场。',1,'meaning'),q('What can plaza mean in American English?','a shopping area with several businesses','a high flat area of land','a written answer in court','plaza 在美式英语中也可指购物商业区。',2,'meaning')]);
P('plea','Plea came through Anglo-French from Old French plait and Medieval Latin placitum; it can be an urgent request, a defendant’s court answer, or a reason offered as an excuse.',[C('plea.s1','恳求；急切请求','The child made a plea for help when the smoke alarm sounded and she could not find her parents.','烟雾警报响起又找不到父母时，孩子急切地呼救。','The child made a plea for help / when the smoke alarm sounded / and she could not find her parents.','plea.s1 指急切、带感情的请求。','孩子在危险中求助。'),C('plea.s2','答辩；认罪或不认罪的陈述','The defendant entered a plea of not guilty at the first hearing and requested a later trial date.','被告在首次听证会上作出无罪答辩，并请求稍后安排审判日期。','The defendant entered a plea of not guilty / at the first hearing / and requested a trial date.','plea.s2 指被告在法庭上对指控作出的认罪或不认罪答辩。','法庭记录明确写出 not guilty。'),C('plea.s3','理由；借口','He offered a plea of exhaustion for missing the meeting, though the calendar showed he had never accepted the invitation.','他以疲惫为由解释缺席会议，但日历显示他从未接受邀请。','He offered a plea of exhaustion / for missing the meeting / though he had never accepted the invitation.','plea.s3 可指为解释或开脱某事而提出的理由。','疲惫被当作缺席的解释。')],M('The defendant entered a plea of guilty while the court record said that he denied the charge and pleaded not guilty.','The defendant entered a plea of not guilty and denied the charge.','认罪与不认罪不能同时成立。','meaning'),[q('Why did the child make a plea for help?','the alarm sounded and she could not find her parents','she wanted to buy a toy train','she was asked to write a stage play','孩子因警报响起且找不到父母而求助。',1,'context'),q('What plea did the defendant enter?','not guilty','guilty','no request for help','被告作出无罪答辩。',2,'context'),q('What was his plea for missing the meeting?','he said he was exhausted','he said he had attended the meeting','he asked to be cast in a play','他以疲惫作为缺席理由。',3,'context'),q('What can plea mean in court?','the answer of guilty or not guilty to a charge','a plaintiff’s role as judge','an enthusiastic round of applause','法庭中的 plea 是对指控认罪或不认罪的答辩。',2,'meaning')]);
P('plead','Plead came from Old French pleder, “argue a case,” related to plea and Latin placitum; it can mean urgently ask, state a court answer, or offer something as an excuse.',[C('plead.s1','恳求；急切请求','The residents pleaded with the council to keep the only night bus running through the winter.','居民恳求市议会冬季继续运营唯一的夜间公交线路。','The residents pleaded with the council / to keep the night bus running / through the winter.','plead.s1 常用 plead with someone to do something，表示急切请求。','居民向主管部门恳求采取行动。'),C('plead.s2','答辩；陈述有罪或无罪','The driver pleaded not guilty in court and asked the judge to review the traffic-camera footage.','司机在法庭上作出无罪答辩，并请求法官查看交通摄像录像。','The driver pleaded not guilty / in court / and asked for the camera footage to be reviewed.','plead.s2 指在法庭上正式回答是否认罪。','司机明确作出 not guilty 答辩。'),C('plead.s3','以……为借口；提出……理由','She pleaded a scheduling conflict for missing rehearsal, but the director checked the calendar before excusing her.','她以时间冲突为由解释缺席排练，但导演在准假前先核对了日历。','She pleaded a scheduling conflict / for missing rehearsal / but the director checked the calendar.','plead.s3 可指把某种理由作为解释或开脱。','她提出时间冲突作为缺席理由。')],M('The residents pleaded for the night bus by telling the council to cancel it and leave the route empty.','The residents pleaded with the council to keep the night bus running.','要求取消公交与恳求继续运营方向相反。','meaning'),[q('What did residents plead with the council to do?','keep the night bus running','remove the bus stop','turn the route into a playground','居民请求冬季保留夜间公交。',1,'context'),q('What did the driver plead in court?','not guilty','exhausted','for the judge to act in a play','司机在法庭上答辩无罪。',2,'context'),q('What did she plead as the reason for missing rehearsal?','a scheduling conflict','a broken blood platelet','an open public plaza','她以时间冲突为缺席排练的理由。',3,'context'),q('Which grammar pattern is correct for a request?','plead with someone to do something','plead someone doing something','plead to someone do something','常用结构是 plead with someone to do。',1,'grammar')]);
P('pleasant','Pleasant came through Old French plaisant, from plaisir and Latin placere, “please”; it describes something that gives enjoyment or comfort.',C('pleasant.s1','令人愉快的；舒适的','A pleasant breeze cooled the courtyard while the guests waited for the outdoor concert to begin.','客人们等待露天音乐会开始时，一阵舒适的微风吹过庭院。','A pleasant breeze cooled the courtyard / while the guests waited / for the concert to begin.','pleasant 形容带来舒适、享受或愉悦感的事物。','凉爽微风让等待变得舒服。'),M('The guests described the icy wind and loud alarm as pleasant because both made them uncomfortable and eager to leave.','The guests described the mild breeze and quiet courtyard as pleasant.','使人不适、想离开的环境不令人愉快。','meaning'),[q('What made the courtyard pleasant?','a cool breeze','a loud alarm','a locked storage closet','凉爽微风带来舒适感。'),q('What does pleasant mean?','giving a feeling of enjoyment or comfort','likely to be false despite appearing true','a formal answer to a charge','pleasant 指令人愉快或舒适的。',1,'meaning'),q('Which setting is pleasant?','a quiet shaded garden on a mild afternoon','a noisy room with smoke and no exits','a freezing hallway under a broken alarm','温和下午安静有荫的花园令人舒适。',1,'context'),q('Which verb is pleasant historically related to?','please','play','plait','pleasant 与 please 同源。',1,'word-formation')]);
P('pleasantly','Pleasantly is formed from pleasant plus -ly; it means in a way that gives mild enjoyment or shows kindness.',C('pleasantly.s1','愉快地；和气地','The receptionist pleasantly explained the new check-in process and offered to help with the bags.','接待员和气地解释了新的入住流程，并主动帮忙拿行李。','The receptionist pleasantly explained the process / and offered / to help with the bags.','pleasantly 修饰行为，表示令人舒服或态度友好。','接待员语气和善并提供帮助。'),M('The receptionist spoke pleasantly by shouting at every guest and refusing to answer any question.','The receptionist spoke pleasantly by answering guests calmly and offering help.','吼叫和拒绝帮助不是和气友善的态度。','meaning'),[q('How did the receptionist explain check-in?','in a friendly and pleasant way','in an angry and threatening way','as a court answer','接待员和气地解释流程。'),q('What does pleasantly mean?','in a way that gives mild pleasure or shows kindness','in a way that proves a claim beyond doubt','in a way that is physically flat','pleasantly 指愉快地或和气地。',1,'meaning'),q('Which person spoke pleasantly?','the clerk who calmly answered questions and smiled','the clerk who shouted and refused to help','the clerk who hid the check-in rules','平静回答问题并微笑的人态度和气。',1,'context'),q('What is the adjective base of pleasantly?','pleasant','plausible','playful','pleasantly 由 pleasant 加 -ly 构成。',1,'word-formation')]);
P('please','Please comes from Old French plaisir and Latin placere, “be acceptable or give pleasure”; it can satisfy someone, make a request polite, or mean do as one wishes.',[C('please.s1','使高兴；使满意','The surprise visit pleased their grandmother, who had hoped to see the grandchildren before the move.','意外来访让祖母很高兴，她原本盼着搬家前见到孙辈。','The surprise visit pleased their grandmother / who had hoped / to see the grandchildren.','please.s1 作动词表示使某人满意或高兴。','来访满足了祖母的愿望。'),C('please.s2','请（礼貌用语）','Please place your visitor badge on the counter before you leave the laboratory.','离开实验室前请把访客证放在柜台上。','Please place your visitor badge / on the counter / before leaving the laboratory.','please.s2 放在请求或指令前使语气更礼貌。','指令以 please 开头。'),C('please.s3','随意；按自己意愿','Guests may arrange the chairs as they please, provided the fire exits remain clear.','只要不挡住消防出口，客人可以按自己的意愿摆放椅子。','Guests may arrange the chairs as they please / provided / the fire exits remain clear.','as you please 等短语中的 please 表示按自己的意愿或选择。','客人可自行安排，但须遵守安全条件。')],M('Please place your badge on the counter, the guard said rudely, and explained that “please” makes the order less polite.','Please place your badge on the counter, the guard said politely, using please to soften the request.','please 用于缓和请求语气，并非使其更粗鲁。','meaning'),[q('What pleased the grandmother?','an unexpected visit from her grandchildren','a change that prevented her from seeing them','a delayed court hearing','孙辈意外来访让祖母高兴。',1,'context'),q('Why does the laboratory instruction begin with please?','to make the request more polite','to say the visitor may choose any badge','to show the badge is made of plastic','please 让指令听起来更礼貌。',2,'meaning'),q('What does “arrange the chairs as they please” mean?','arrange them as they wish, subject to the safety condition','ask someone to arrange them politely','make the chairs feel happy','as they please 指按自己的意愿安排。',3,'meaning'),q('Which use of please expresses satisfaction?','The thoughtful gift pleased the new neighbors.','Please leave your key at reception.','You may sit wherever you please.','第一句中 please 表示使人高兴。',1,'meaning')]);
P('pleased','Pleased is the past participle and adjective from please; it means feeling or showing happiness or satisfaction.',C('pleased.s1','高兴的；满意的','The curator was pleased when the repaired painting returned without a scratch.','修复后的画作毫无刮痕地送回时，馆长很满意。','The curator was pleased / when the repaired painting returned / without a scratch.','pleased 描写感到高兴或满意的状态，常与 be 连用。','修复结果达到馆长的期待。'),M('The curator was pleased with the damaged painting and said she was angry that it had been repaired successfully.','The curator was pleased that the painting had been repaired successfully without damage.','满意与因成功修复而生气语义矛盾。','meaning'),[q('Why was the curator pleased?','the painting returned repaired and undamaged','the painting was lost during transport','the playhouse closed permanently','画作修好且无损地归还，馆长感到满意。'),q('What does pleased mean?','feeling or showing happiness or satisfaction','asking urgently for help','sounding likely but not proven','pleased 指感到或表现出高兴、满意。',1,'meaning'),q('Which person is pleased?','a visitor smiling after a helpful tour','a visitor shouting after being misled','a witness changing a court plea','满意的游客会面带微笑。',1,'context'),q('Which verb is pleased derived from?','please','plead','play','pleased 是动词 please 的过去分词形式。',1,'word-formation')]);
P('pleasing','Pleasing is the present-participle adjective of please, from Old French plaisir and Latin placere “to be acceptable”; it describes something attractive or satisfying.',C('pleasing.s1','令人喜欢的；舒服的','The architect chose a pleasing balance of warm wood, soft light, and open space for the small reading room.','建筑师为小阅览室安排了悦目的搭配：温暖的木材、柔和的灯光和开阔的空间。','The architect chose a pleasing balance / of warm wood, soft light, and open space / for the reading room.','pleasing 修饰令人感到满意或舒服的设计组合。','色彩、灯光与空间搭配和谐，因此整体观感舒服。'),M('The architect called the harsh fluorescent glare pleasing, although every visitor covered their eyes and left.','The architect chose a pleasing, softly lit design that visitors found comfortable.','刺眼的灯光使访客遮眼离开，与令人舒服的设计相反。','meaning'),[q('What did the architect balance in the reading room?','warm wood, soft light, and open space','bare concrete, glaring lights, and a blocked doorway','folded cloth and farm tools','设计师搭配了木材、柔光和开阔空间。'),q('What does pleasing describe here?','attractive or satisfying','dangerous and difficult','slow but steady','pleasing 指令人喜欢或满意的。',1,'meaning'),q('Which room has a pleasing design?','one with calm light and a comfortable arrangement','one with blinding glare and no clear walkway','one where the furniture is deliberately broken','柔和灯光和舒适布局带来悦目效果。',1,'context'),q('Which verb is pleasing the present-participle form of?','please','pleat','plod','pleasing 是 please 的现在分词形容词。',1,'word-formation')]);
P('pleasurable','Pleasurable combines pleasure with -able and has meant “giving or capable of giving pleasure” since the 1570s.',C('pleasurable.s1','快乐的；令人愉快的','The coastal walk was pleasurable because the path was quiet, the weather mild, and the view open to the sea.','这段海岸步道令人愉快：道路安静，天气温和，还能望见开阔的海面。','The coastal walk was pleasurable / because the path was quiet / and the weather was mild.','pleasurable 形容带来享受或愉快感的经历。','安静的道路、舒适天气和海景使散步成为愉快体验。'),M('The supposedly pleasurable hike left everyone miserable because the guide forced the group to walk barefoot over sharp glass.','The pleasurable hike followed a safe coastal path in mild weather.','赤脚踩过碎玻璃令人痛苦，不是令人愉快的经历。','meaning'),[q('Why did the group find the coastal walk pleasurable?','the quiet path, mild weather, and sea view','the sharp glass and dangerous route','the loud courtroom and long delay','安静、安全、景色开阔使散步愉快。'),q('What does pleasurable mean?','giving or capable of giving enjoyment','filled beyond a reasonable amount','able to bend without breaking','pleasurable 指能带来快乐或享受的。',1,'meaning'),q('Which activity sounds pleasurable?','a calm walk beside the sea on a mild day','a barefoot march over broken glass','a tiring wait in a locked room','天气舒适、沿海散步可以令人愉快。',1,'context'),q('How is pleasurable formed?','pleasure + -able','pleat + -ful','plough + -er','pleasurable 由 pleasure 加 -able 构成。',1,'word-formation')]);
P('pleasure','Pleasure comes through Old French plesir/plaisir from Latin placere “to please”; it names a happy feeling, a source of enjoyment, or an honor.',[C('pleasure.s1','快乐；快感','She felt genuine pleasure when the community garden produced its first tomatoes after months of careful work.','经过数月精心照料，社区花园结出第一批番茄时，她由衷地感到快乐。','She felt genuine pleasure / when the garden produced its first tomatoes / after months of care.','pleasure.s1 指人内心感受到的快乐或满足。','长期照料后看到收获，使她感到高兴。'),C('pleasure.s2','乐事；荣幸','It was a pleasure to introduce the visiting scientist, whose research had inspired the whole class.','能介绍这位鼓舞了全班的来访科学家，是我的荣幸。','It was a pleasure to introduce the scientist / whose research / had inspired the class.','pleasure.s2 可指带来快乐的事情，也常用于礼貌表达荣幸。','说话者把介绍来访者视为荣幸。')],M('It was a pleasure to meet the guest, the host said, then explained that the meeting had made him deeply unhappy.','It was a pleasure to meet the guest, the host said, because he was glad to welcome her.','“很荣幸见到”与“因此非常不开心”在语境中互相矛盾。','context'),[q('What gave her pleasure in the garden?','seeing the first tomatoes after months of care','finding that every plant had died','being asked to cancel the harvest','看到辛苦栽种的番茄成熟使她快乐。',1,'context'),q('Why did the speaker say “It was a pleasure to introduce” the scientist?','the introduction was an honor and a welcome experience','the speaker wanted to show that the visit caused pain','the scientist had refused to meet the class','It was a pleasure to… 是礼貌表达荣幸的说法。',2,'meaning'),q('Which use of pleasure names a feeling?','She felt pleasure when the seedlings began to grow.','It was a pleasure to welcome the honored guest.','The invitation is a pleasure for the entire school.','第一句直接表示内心感到快乐。',1,'meaning'),q('Which Latin verb is the source of pleasure through Old French?','placere, “to please”','plicare, “to fold”','plodere, “to walk slowly”','pleasure 经古法语来自拉丁语 placere。',1,'word-formation')]);
P('pleat','Pleat is a spelling and pronunciation variant of plait: the noun means a fold in cloth, and the verb means to press folds into fabric.',[C('pleat.s1','褶；褶裥','A deep pleat in the skirt gave the fabric room to move when the dancer took a long step.','裙子上的一道深褶让舞者迈大步时有足够的活动空间。','A deep pleat in the skirt / gave the fabric room / when the dancer took a long step.','pleat.s1 作名词指压在布料上的一道褶。','褶裥增加布料的活动余量。'),C('pleat.s2','给……打褶','The costume maker pleated the blue fabric by pressing a row of narrow folds before sewing the waistband.','服装师先把蓝布压出一排窄褶，再缝上腰带。','The costume maker pleated the fabric / by pressing narrow folds / before sewing the waistband.','pleat.s2 作动词，表示把布料压出褶裥。','先压褶再缝腰带，说明 pleated 是对布料进行的动作。')],M('The tailor pleated the skirt by flattening every fold until the fabric had no creases at all.','The tailor pleated the skirt by pressing neat folds into the fabric.','把褶全部压平会消除褶裥，不会形成褶。','meaning'),[q('What did the deep pleat allow the dancer to do?','take a long step more easily','keep the skirt completely flat','turn a field into a farm','褶裥给布料留出活动空间。',1,'context'),q('How did the costume maker pleat the blue fabric?','by pressing a row of narrow folds','by cutting all the fabric into separate strips','by smoothing every crease out','打褶是压出一排窄折痕。',2,'context'),q('What is a pleat.s1?','a fold pressed into cloth','a promise made in public','a direct vote by the people','pleat.s1 指布料上的一道褶。',1,'meaning'),q('Which word is pleat a variant of?','plait','plod','plot','pleat 是 plait 的拼写/发音变体。',1,'word-formation')]);
P('plebeian','Plebeian comes from Latin plebeius, “belonging to the plebs, the common people”; it names a commoner or describes something common or, by extension, unrefined.',[C('plebeian.s1','平民','The historian explained that a plebeian in ancient Rome belonged to the common population rather than the patrician elite.','历史学家解释说，古罗马的平民属于普通民众，而不是贵族阶层。','A plebeian in ancient Rome / belonged to the common population / rather than the patrician elite.','plebeian.s1 作名词，指古罗马平民或普通民众。','句中与 patrician elite 对比，明确指出社会身份。'),C('plebeian.s2','平民的；粗俗的','The critic called the joke plebeian because it relied on crude insults instead of wit.','评论家认为这个笑话粗俗，因为它靠低俗辱骂而不是机智取笑。','The critic called the joke plebeian / because it relied on crude insults / instead of wit.','plebeian.s2 作形容词可指平民的，也可贬义地指粗俗、不高雅的。','这里的贬义来自低俗辱骂与机智幽默的对照。')],M('The museum guide called the Roman plebeian a member of the patrician ruling class and said the two ranks were identical.','The museum guide described a plebeian as a common Roman citizen, not a patrician.','plebeians 与 patricians 是古罗马不同阶层，不能说平民属于贵族。','confusable'),[q('How did the historian distinguish a plebeian from a patrician?','the plebeian belonged to the common population','the plebeian was necessarily a senator','the plebeian was a Roman law code','平民属于普通民众，与贵族阶层相对。',1,'context'),q('Why was the joke called plebeian?','it used crude insults rather than wit','it used refined wordplay and subtle humor','it recorded an official public vote','粗俗辱骂使笑话显得低俗。',2,'context'),q('What is a plebeian.s1?','a member of the common people','a member of the ancient Roman elite','a folded strip of fabric','plebeian.s1 作名词指平民。',1,'meaning'),q('Which source word does plebeian derive from?','Latin plebeius, “of the common people”','Latin plicare, “to fold”','Greek pleistos, “most”','plebeian 源自拉丁语 plebeius。',1,'word-formation')]);
P('plebiscite','Plebiscite came through French from Latin plebiscitum, a “decree of the people,” formed from plebs “common people” and scitum “decree.”',C('plebiscite.s1','公民投票','The residents approved the new constitution in a plebiscite, with every eligible voter marking one of two choices.','居民通过公民投票批准了新宪法，每位合资格选民都在两个选项中选择其一。','The residents approved the constitution / in a plebiscite / with each eligible voter choosing.','plebiscite 指全体人民就重要问题进行的直接投票。','选民直接投票决定宪法问题，符合公民投票的含义。'),M('The newspaper called a private dinner among three ministers a plebiscite, although no public vote took place.','The newspaper called the public vote on the constitutional question a plebiscite.','只有少数官员私下会餐、没有全民直接投票，不是公民投票。','meaning'),[q('What did residents decide in the plebiscite?','whether to approve the new constitution','which fabric fold to sew into a skirt','how to divide a small garden plot','选民投票决定是否批准新宪法。'),q('What is a plebiscite?','a direct vote of the people on an important question','a secret plan to harm an official','a promise to repay a loan','plebiscite 指人民就重要问题进行直接投票。',1,'meaning'),q('Which event is a plebiscite?','eligible citizens vote directly on a national question','a cabinet member privately signs a promise','a judge describes a person’s difficult situation','公民直接投票决定国家问题，符合 plebiscite。',1,'context'),q('Which Latin parts compose plebiscitum?','plebs “the people” + scitum “decree”','plenus “full” + -ful “full of”','plicare “fold” + -able “able to”','拉丁语 plebiscitum 由 plebs 与 scitum 构成。',1,'word-formation')]);
P('pledge','Pledge entered English from Old French plege, “surety or security”; the related verb can mean to promise, commit money, or leave property as loan security.',[C('pledge.s1','誓言；保证','Before the campaign began, each volunteer made a public pledge to report donations accurately.','竞选活动开始前，每位志愿者都公开承诺如实报告捐款。','Each volunteer made a public pledge / to report donations accurately / before the campaign began.','pledge.s1 作名词指郑重作出的承诺。','承诺被公开作出，并明确说明将履行的事项。'),C('pledge.s2','承诺；保证给予','The company pledged two million dollars to rebuild the town library after the storm.','风暴过后，公司承诺捐出两百万美元重建镇图书馆。','The company pledged two million dollars / to rebuild the library / after the storm.','pledge.s2 作动词表示郑重承诺做某事或提供某物。','pledged 的宾语是承诺提供的捐款。'),C('pledge.s3','抵押品；以……抵押','To secure the small business loan, the owner pledged the delivery van as collateral.','为获得小企业贷款，店主把送货车作为抵押品。','The owner pledged the van / as collateral / to secure the business loan.','pledge.s3 可指用于担保的财物，也可表示以财物作抵押。','送货车被提供为贷款担保。')],M('The company pledged two million dollars to the library, then insisted that “pledged” meant it had already received the money back.','The company pledged two million dollars to the library, promising to provide the funds.','pledge 在此表示承诺提供资金，不表示收回资金。','meaning'),[q('What did volunteers pledge to do?','report donations accurately','keep every donation secret from auditors','use a van as loan collateral','志愿者公开承诺如实报告捐款。',1,'context'),q('What did the company pledge after the storm?','two million dollars for rebuilding the library','the library building as security for a loan','a promise that no funds would be given','公司承诺捐款重建图书馆。',2,'context'),q('What did the owner pledge as collateral?','the delivery van','the new library books','a public speech','送货车被用作贷款抵押品。',3,'context'),q('Which meaning fits “pledge to provide funds”?','make a serious promise to give something','fold cloth into a narrow crease','walk slowly through mud','pledge 可表示郑重承诺给予某物。',2,'meaning')]);
P('Pleistocene','Pleistocene was coined in 1839 by geologist Charles Lyell from Greek pleistos “most” and -cene “recent”; it names the epoch before the Holocene, marked by repeated glaciations.',C('Pleistocene.s1','更新世','The cave layer contained Pleistocene animal fossils deposited during a period when glaciers covered much of the region.','洞穴地层中有更新世动物化石；当时冰川覆盖了该地区的大片土地。','The cave layer contained Pleistocene fossils / deposited during an epoch / when glaciers covered much of the region.','Pleistocene.s1 指全新世之前、经历多次冰期的地质世。','冰川活动与更新世相符，化石出自该时期地层。'),M('The guide dated the Pleistocene layer to the age after the Holocene and before the first ice sheets existed.','The guide dated the Pleistocene layer to the epoch before the Holocene, when repeated glaciations occurred.','更新世在全新世之前，并以多次冰期为特征。','meaning'),[q('What did the cave layer contain?','animal fossils from a glacial epoch','a written Roman plebiscite','a promise to donate a library','洞穴地层含有冰期动物化石。'),q('Which epoch does Pleistocene name?','the epoch before the Holocene with repeated glaciations','the period after the Holocene with no glaciers','the time when the first Roman plebeians voted','更新世是全新世之前经历多次冰期的时期。',1,'meaning'),q('Which discovery would support a Pleistocene date?','fossils in a layer formed during repeated glaciations','a modern receipt showing a recent purchase','a map of a small garden plot','冰期沉积层中的动物化石支持更新世年代判断。',1,'context'),q('What does the element -cene refer to in Pleistocene?','recent or new','folded cloth','a public promise','-cene 在地质时期名称中表示“新近”。',1,'word-formation')]);
P('plenteous','Plenteous came through Old French plentivos from plentee “abundance”; it is a formal adjective meaning present in large amounts.',C('plenteous.s1','丰饶的','The orchard gave a plenteous harvest, filling the storage room with apples before the first frost.','果园收成丰饶，初霜到来前储藏室已经堆满苹果。','The orchard gave a plenteous harvest / filling the storage room / before the first frost.','plenteous 形容收成数量丰富，语体比 plentiful 更书面。','苹果丰收并装满储藏室，体现数量充足。'),M('The orchard produced a plenteous harvest of only one spoiled apple, leaving every storage shelf empty.','The orchard produced a plenteous harvest that filled the storage room with sound apples.','一颗腐烂的苹果且货架全空不能称为丰收。','meaning'),[q('What filled the storage room?','apples from the orchard’s large harvest','empty boxes after a failed harvest','folded cloth from a tailor','丰收的苹果装满储藏室。'),q('What does plenteous mean?','present in large amounts','difficult and painful','able to bend easily','plenteous 指数量丰饶的。',1,'meaning'),q('Which harvest is plenteous?','one that fills several storage rooms with fruit','one that produces only a spoiled apple','one in which no crops grow','大量收获水果可称为 plenteous。',1,'context'),q('Which older French form is related to plenteous?','plentivos, from plentee “abundance”','plebeius, “common person”','pleit, “a fold”','plenteous 经古法语 plentivos 与 plentee 有关。',1,'word-formation')]);
P('plentiful','Plentiful is formed from plenty + -ful; it means existing in large quantities.',C('plentiful.s1','丰富的；大量的','Fresh drinking water was plentiful after the reservoir filled during the spring rains.','春雨让水库蓄满后，洁净饮用水供应充足。','Fresh drinking water was plentiful / after the reservoir filled / during the spring rains.','plentiful 作形容词，描述某物数量很多。','水库水量上升意味着可用饮用水充足。'),M('Fresh water was plentiful in the village because every well had dried up and the residents had no water to drink.','Fresh water was plentiful in the village because full wells supplied more than enough for residents.','井都干涸且无水可饮表示短缺，与 plentiful 相反。','meaning'),[q('Why was fresh water plentiful?','the reservoir had filled after spring rains','every well had dried up','the village had lost its only water source','春雨使水库蓄满，水源充足。'),q('What does plentiful mean?','existing in large quantities','scarce and hard to find','pleasant but not exciting','plentiful 指大量存在的。',1,'meaning'),q('Which resource is plentiful?','a crop harvested in such abundance that every market has stock','a medicine unavailable at every pharmacy','a fuel supply reduced to the last drop','各市场都有充足存货说明收成丰富。',1,'context'),q('What suffix is added to plenty in plentiful?','-ful','-less','-ment','plentiful 由 plenty 加 -ful 构成。',1,'word-formation')]);
P('plentifully','Plentifully is the adverb formed from plentiful + -ly; it describes something supplied or occurring in abundance.',C('plentifully.s1','充裕地；大量地','Rain fell plentifully through the night, filling the farm pond and soaking the dry fields.','夜里降雨充沛，农场池塘蓄满，干旱的田地也湿透了。','Rain fell plentifully / through the night / filling the pond and soaking the fields.','plentifully 修饰动词 fell，说明降雨发生得很充足。','大量降雨让池塘蓄满并浸湿田地。'),M('Rain fell plentifully because only two drops reached the dry farm all night.','Rain fell plentifully, soaking the dry fields and filling the pond.','只有两滴雨表示雨量稀少，不是充沛地降雨。','meaning'),[q('What happened after rain fell plentifully?','the farm pond filled and dry fields became wet','the pond dried up and fields stayed dusty','the orchard produced a small number of apples','充沛降雨使池塘蓄满、田地湿润。'),q('What does plentifully mean?','in a large or abundant amount','in a slow and laborious way','in a vulgar or unrefined manner','plentifully 表示充足、大量地。',1,'meaning'),q('Which sentence uses plentifully as an adverb?','Wildflowers grew plentifully along the wet hillside.','The hillside was plentifully flowers.','A plentifully of flowers covered the hill.','plentifully 修饰 grew，表达野花大量生长。',1,'grammar'),q('Which adjective is the base of plentifully?','plentiful','plenteousness','plebeian','plentifully 由形容词 plentiful 加 -ly 构成。',1,'word-formation')]);
P('plenty','Plenty came through Old French plentee from Latin plenitas “fullness”; it can mean a large amount, a condition of abundance, or “more than enough” before an adjective.',[C('plenty.s1','大量；充足','We packed plenty of drinking water for the long hike, so nobody had to ration a small bottle.','长途徒步时我们带了充足的饮用水，因此没人需要省着喝一小瓶水。','We packed plenty of drinking water / for the long hike / so nobody had to ration it.','plenty.s1 通常用于 plenty of + 名词，表示大量或足够多。','水量足够，无需节省。'),C('plenty.s2','富裕；丰足（名词）','After years of poor harvests, the region finally enjoyed a season of plenty, with full markets and food stores.','多年歉收后，这个地区终于迎来丰足的一年，市场和粮仓都满了。','The region enjoyed a season of plenty / with full markets / after years of poor harvests.','plenty.s2 作名词表示富足、丰裕的状态。','市场和粮仓充满食物，说明整体丰足。'),C('plenty.s3','相当；十足（副词）','The rescue team arrived plenty early, leaving time to check the ropes before the storm reached the ridge.','救援队早到了不少，在暴风雨抵达山脊前还有时间检查绳索。','The rescue team arrived plenty early / leaving time / to check the ropes.','plenty.s3 在非正式用法中可置于形容词或副词前，表示“很、相当”。','plenty 修饰 early，表示远早于必要时间。')],M('We packed plenty of informations for the hike, although the guide explained that the plural count noun was “water.”','We packed plenty of water for the hike, bringing more than enough for everyone.','information 不可数，不能用 informations；此处应接 water。','countability'),[q('Why did nobody need to ration water?','the group had packed plenty for the long hike','each hiker carried only a tiny bottle','the trail had no water at all','充足的水无需节省饮用。',1,'context'),q('What is a “season of plenty”?','a time of general abundance and full supplies','a season when every market is empty','a promise to donate a particular sum','season of plenty 指普遍丰裕的时期。',2,'meaning'),q('In “arrived plenty early,” what does plenty mean?','more than enough; considerably','a large number of objects','a formal public promise','plenty 修饰 early，表示早了很多。',3,'meaning'),q('Which phrase is grammatically correct?','plenty of information','plenty of informations','plentifully information','information 是不可数名词，应用 plenty of information。',1,'grammar')]);
P('plethora','Plethora came through Late Latin from Greek plēthōrē “fullness”; its modern general sense is a very large, often excessive supply.',C('plethora.s1','过多；大量','The report offered a plethora of statistics, so the editor removed several tables that repeated the same point.','报告提供了大量统计数据，因此编辑删掉了几张重复表达同一观点的表格。','The report offered a plethora of statistics / so the editor removed tables / that repeated the same point.','plethora 常指极多的数量，有时暗含多到过量。','表格数量过多且重复，编辑选择删减。'),M('The report contained a plethora of exactly one statistic, leaving most of its claims unsupported.','The report contained a plethora of statistics, including many that repeated the same point.','只有一条统计数字不是大量或过量。','meaning'),[q('Why did the editor remove several tables?','the report had an excessive number of statistics and repetitions','the report contained no tables or data','the report was a public vote','报告数据表过多且重复，所以编辑删减。'),q('What does plethora mean?','a very large or excessive supply','a promise offered as loan security','a fold pressed into cloth','plethora 指大量，常带“过多”意味。',1,'meaning'),q('Which situation shows a plethora of choices?','a menu listing so many similar dishes that customers struggle to choose','a shop with one item and no alternatives','a field that has just been ploughed','大量相似菜品使人难以选择，体现数量过多。',1,'context'),q('Which Greek word is the source of plethora?','plēthōrē, “fullness”','plebeius, “common person”','placere, “to please”','plethora 源自希腊语 plēthōrē“充满”。',1,'word-formation')]);
P('plethoric','Plethoric is formed from plethora and -ic; it means overfull or swollen with excess and is often used in formal or medical descriptions.',C('plethoric.s1','过多的；充盈的','The reviewer found the appendix plethoric with minor tables, many of which repeated results already shown in the main text.','评论者认为附录里塞满了琐碎表格，其中许多重复了正文已经呈现的结果。','The reviewer found the appendix plethoric / with minor tables / many of which repeated earlier results.','plethoric 表示过度充满，语气较正式。','大量冗余表格造成附录过于臃肿。'),M('The appendix was plethoric with empty pages and contained no table, figure, or data at all.','The appendix was plethoric with repeated tables and unnecessary figures.','空白且没有任何内容不能称为充满过量材料。','meaning'),[q('What made the appendix plethoric?','many minor tables repeated results from the main text','the appendix contained no tables or data','the reviewer removed every page','重复的琐碎表格让附录显得过度充实。'),q('What does plethoric mean here?','overfull or swollen with excess','present in only a tiny amount','easy to bend without breaking','plethoric 指过度充满的。',1,'meaning'),q('Which appendix is plethoric?','one crowded with redundant charts and tables','one with a single concise figure','one that is completely blank','冗余图表塞满附录，符合 plethoric。',1,'context'),q('Which noun is plethoric derived from?','plethora','plough','pleat','plethoric 由 plethora 加 -ic 构成。',1,'word-formation')]);
P('pliable','Pliable came through Old French ploiable from plier and Latin plicare “to fold”; it describes material that bends without breaking and, figuratively, a yielding disposition.',C('pliable.s1','柔韧的；易弯曲的','The craft worker heated the pliable reed and bent it into a smooth curve without snapping it.','手工艺者把柔韧的芦苇加热，弯成平滑曲线而没有折断。','The craft worker heated the pliable reed / and bent it into a curve / without snapping it.','pliable 描写受力后容易弯曲而不破裂的材料。','芦苇能够弯曲成形但未折断，说明它柔韧。'),M('The glass rod was pliable, so it snapped into sharp pieces as soon as the worker bent it gently.','The pliable reed bent smoothly under pressure without snapping.','轻轻弯曲便折断说明材料不柔韧。','meaning'),[q('What did the craft worker do with the pliable reed?','bent it into a smooth curve without breaking it','crushed it into sharp fragments','used it as a loan pledge','芦苇弯曲成形且没有折断。',1,'context'),q('What does pliable mean literally?','able to bend without breaking','swollen with excessive fluid','able to make a secret plan','pliable 的字面义是易弯而不断裂。',1,'meaning'),q('Which object is pliable?','a thin reed that bends into a curve and remains intact','a brittle glass rod that shatters on slight pressure','a heavy stone that cannot flex','柔韧的芦苇受力后会弯而不断。',1,'context'),q('Which Latin verb is related to pliable through French plier?','plicare, “to fold”','placere, “to please”','sciscere, “to vote”','pliable 最终与拉丁语 plicare“折叠”有关。',1,'word-formation')]);
P('pliant','Pliant comes from Old French ploiant, the participle of ploier “to bend,” from Latin plicare; it can describe something flexible or a person readily influenced.',C('pliant.s1','柔韧的；易被说服的','After the evidence was presented, the pliant committee chair agreed to revise the policy rather than defend the flawed draft.','证据摆出后，容易被说服的委员会主席同意修改政策，而不是继续维护有缺陷的草案。','The pliant committee chair agreed to revise the policy / after the evidence was presented / rather than defend the draft.','pliant 可形容容易受影响、改变立场的人，也可形容柔韧的物体。','主席依据证据改变立场，体现容易被说服这一比喻义。'),M('The pliant chair refused to consider any evidence and kept the same position regardless of every argument.','The pliant chair changed the policy after considering the new evidence.','拒绝受任何论据影响与 pliant 的“易被影响”义相反。','meaning'),[q('Why did the committee chair change the policy?','the evidence persuaded the pliant chair','the chair refused to consider the evidence','the committee voted on a plebiscite','主席接受证据并同意修改政策。',1,'context'),q('What does pliant mean in this passage?','readily influenced or persuaded','overfull with repeated material','a common person in ancient Rome','pliant 指容易受影响或说服的。',1,'meaning'),q('Which person is pliant?','a negotiator who adjusts a view after hearing sound evidence','a negotiator who never changes a view under any circumstances','a farmer turning soil with a plough','根据证据调整观点的人容易受影响。',1,'context'),q('Which French verb is related to pliant?','ploier, “to bend”','plaisir, “to please”','pleurer, “to cry”','pliant 与古法语 ploier“弯曲”有关。',1,'word-formation')]);
P('plight','The noun plight has a layered history: the sense “condition” is linked to Old French plit/pleit, originally a way of folding; the source for the separate “pledge” sense is distinct and uncertain.',[C('plight.s1','困境；苦境','After the flood destroyed the bridge and the clinic, the isolated village was in a serious plight.','洪水冲毁桥梁和诊所后，这座与外界隔绝的村庄陷入严重困境。','The village was in a serious plight / after the flood destroyed / the bridge and clinic.','plight.s1 指严重而棘手的处境。','交通和医疗设施被毁，使村庄面临艰难局面。'),C('plight.s2','悲惨境遇','The charity shared the displaced families’ plight so that donors would understand their need for warm shelter.','慈善机构介绍流离失所家庭的悲惨境遇，让捐助者了解他们急需温暖的住所。','The charity shared the families’ plight / so donors would understand / their need for shelter.','plight.s2 强调某个人或群体正在承受的苦难、困境。','家庭流离失所并缺少住所，属于需要帮助的苦境。')],M('The village was in a plight because the flood had repaired its bridge, reopened the clinic, and restored every service.','The village was in a plight because the flood destroyed the bridge and left residents without medical care.','桥梁和服务恢复表示困境缓解，并非陷入困境。','meaning'),[q('Why was the village in a serious plight?','the flood destroyed its bridge and clinic','the flood restored transport and medical services','the village received a large harvest','设施被洪水毁坏使村庄陷入困境。',1,'context'),q('What does plight.s2 emphasize?','the suffering condition of people who need help','a direct vote by all eligible citizens','a pressed fold in cloth','plight.s2 强调群体正在承受、需要帮助的苦境。',2,'meaning'),q('Which group’s plight did the charity publicize?','displaced families needing warm shelter','visitors enjoying a comfortable walk','farmers celebrating plentiful crops','流离失所且需要住所的家庭处于苦境。',2,'context'),q('Which history applies to the noun sense “condition”?','it is linked through Old French plit/pleit to a word for a way of folding','it certainly derives from Greek for “most recent”','it is a modern blend of plenty and -ful','困境义与古法语 plit/pleit 及“折叠方式”有关。',1,'word-formation')]);
P('plod','Plod is first recorded in the 1560s for trudging or working slowly and steadily; its origin is uncertain and may imitate the sound of heavy steps.',C('plod.s1','缓慢地走；埋头苦干','The hikers plodded through ankle-deep mud for hours, taking each step carefully until they reached the cabin.','徒步者在齐踝深的泥里缓慢前行数小时，小心迈步，终于到达小屋。','The hikers plodded through the mud / taking each step carefully / until they reached the cabin.','plod.s1 作动词可指费力缓慢地走，也可指持续而缓慢地工作。','泥泞路途艰难，徒步者一步步缓慢前进。'),M('The hikers plodded up the hill by sprinting lightly and reaching the cabin in a few seconds.','The hikers plodded through the deep mud one slow, heavy step at a time.','短时间轻快冲刺与缓慢费力地行走相反。','meaning'),[q('How did the hikers move through the mud?','slowly and carefully, one step at a time','quickly and effortlessly in a sprint','by turning the soil with a farm tool','徒步者在泥中费力缓慢前行。'),q('What does plod mean?','to walk slowly with effort or work steadily and slowly','to vote directly on a national question','to press folds into fabric','plod 指缓慢费力地走或持续缓慢地做事。',1,'meaning'),q('Which student is plodding through an assignment?','one who works steadily through each problem at a slow pace','one who guesses every answer and leaves immediately','one who folds the paper into pleats','稳定而缓慢地逐题完成作业符合 plod 的比喻用法。',1,'context'),q('What is known about the origin of plod?','it is uncertain and may imitate heavy footsteps','it is certainly from Latin plenitas “fullness”','it was coined from Greek pleistos “most”','plod 的来源不确定，可能是拟声形成。',1,'word-formation')]);
P('plot','Plot has uncertain origins for its old sense “small piece of ground”; its later senses include a story’s events, a harmful secret plan, and the verbs for planning secretly or mapping points.',[C('plot.s1','情节','The novel’s plot follows a missing violin from a village auction to a concert hall, revealing the thief only in the final chapter.','这部小说的情节围绕一把失窃的小提琴，从乡村拍卖会一路追到音乐厅，直到最后一章才揭露窃贼。','The novel’s plot follows the missing violin / from the auction to the concert hall / revealing the thief at the end.','plot.s1 指小说、电影或戏剧中的主要事件脉络。','失窃小提琴和追查过程构成故事的事件线。'),C('plot.s2','阴谋；密谋','Investigators uncovered a plot to sabotage the election computers before the national vote.','调查人员揭露了一场在全国投票前破坏选举电脑的阴谋。','Investigators uncovered a plot / to sabotage election computers / before the national vote.','plot.s2 指秘密策划的有害或非法行动。','计划秘密破坏选举设备，符合阴谋义。'),C('plot.s3','小块土地','The family planted tomatoes and beans in a small plot behind the apartment building.','这家人在公寓楼后的一小块地里种了番茄和豆子。','The family planted vegetables / in a small plot / behind the apartment building.','plot.s3 指为某一用途划出的一小块土地。','蔬菜种在界限明确的小片土地上。'),C('plot.s4','密谋；标绘','During the survey, the engineer plotted each bridge support on the map and checked its measured coordinates.','测绘时，工程师把每根桥梁支座标绘在地图上，并核对其测量坐标。','The engineer plotted each support / on the map / and checked its coordinates.','plot.s4 作动词既可指秘密策划，也可指在地图或图表上标出点位。','工程师把测量点标到地图上，体现动词的标绘义。')],M('The investigators called the public novel’s sequence of chapters a plot to sabotage the election computers, though no secret plan existed.','The investigators called the secret plan to sabotage the election computers a plot.','普通小说情节与秘密破坏行动不是同一个含义；此处没有阴谋。','confusable'),[q('How does the novel reveal the thief?','only in the final chapter of its story','through a public vote before the auction','by marking bridge supports on a map','小提琴失窃事件构成小说情节，窃贼在最后揭晓。',1,'context'),q('What did investigators uncover before the vote?','a secret plan to sabotage election computers','a small vegetable garden plot','a novel about a missing violin','秘密破坏选举电脑是阴谋。',2,'context'),q('What is the family’s small plot?','a piece of land used to grow vegetables','the secret plan uncovered by investigators','the main events of a novel','plot.s3 指种植蔬菜的一小块土地。',3,'meaning'),q('What did the engineer do when she plotted each bridge support?','marked its position on a map using measured coordinates','planned secretly to damage the bridge','wrote the novel’s final chapter','plot 作动词可指在地图上标绘点位。',4,'meaning')]);
P('plough','Plough is the British spelling of plow; the noun names a soil-turning farm tool, and the verb can mean to till soil or push laboriously through difficulty.',[C('plough.s1','犁','The farmer attached the plough to the tractor and checked that its blade could cut and turn the compacted soil.','农民把犁连接到拖拉机上，并检查犁刃能否切开、翻转坚硬的土壤。','The farmer attached the plough / and checked its blade / before turning the soil.','plough.s1 作名词指切入并翻转土壤的农具。','犁刃用来破土并翻土。'),C('plough.s2','耕；犁地','After the first frost, the farmer ploughed the field to prepare the soil for spring planting.','初霜过后，农民犁地，为春季播种准备土壤。','The farmer ploughed the field / to prepare the soil / for spring planting.','plough.s2 作动词表示用犁翻耕土地。','翻土为下一季播种做准备。'),C('plough.s3','艰难前行；埋头苦干','The research team ploughed through hundreds of damaged records before finding the missing measurements.','研究团队埋头检查数百份受损记录，终于找到了缺失的测量数据。','The research team ploughed through damaged records / before finding / the missing measurements.','plough through 可比喻费力地处理大量困难材料。','检查大量受损记录既费时又困难，团队仍持续完成。')],M('The farmer ploughed the field by using the tractor blade to smooth the soil without turning it or preparing it for crops.','The farmer ploughed the field by cutting and turning the soil before spring planting.','耕地是翻动土壤；只把表面压平不是犁地。','meaning'),[q('What did the plough’s blade do?','cut and turn the compacted soil','fold cloth into narrow pleats','mark a secret plan on a chart','犁刃切开并翻转土壤。',1,'context'),q('Why did the farmer plough the field after the frost?','to prepare the soil for spring planting','to make the field a public vote','to harvest apples from the orchard','犁地为春季播种做准备。',2,'context'),q('What does “ploughed through hundreds of records” mean?','worked laboriously through a large, difficult set of records','used a farm tool to turn paper into soil','made a secret plan to hide the measurements','plough through 比喻费力处理大量材料。',3,'meaning'),q('Which spelling is the British form of the noun and verb?','plough','plowt','plaut','plough 是 plow 的英式拼写。',1,'word-formation')]);
})();

